INSERT INTO public.cursos (id, titulo, slug, descripcion, objetivo, imagen_portada_url, duracion_estimada_min, nivel_dificultad, categoria_id, estado, autor_id, porcentaje_aprobacion, max_intentos, navegacion, es_diplomado, empresa_id, created_at, updated_at, deleted_at) VALUES ('e649f9ae-9c62-4dfa-bf36-341e0f79007d', 'DIPLOMADO EN GERENCIA SOCIAL', 'diplomado-en-gerencia-social', 'El Diplomado de Gerencia Social se centra en el desarrollo y la implementación de políticas, programas y proyectos destinados a mejorar el bienestar social, especialmente en comunidades vulnerables. Se fundamenta en principios como la participación ciudadana, la equidad, la justicia social y el respeto a los derechos humanos. Abarca temas como la responsabilidad social empresarial, la gestión de conflictos sociales y la construcción de paz, proporcionando a los estudiantes herramientas prácticas para intervenir eficazmente en estos ámbitos.', 'Formar a los participantes en el diseño, planificación, ejecución y evaluación de proyectos sociales, con el fin de mejorar la calidad de vida de las comunidades y promover el desarrollo sostenible. Se busca dotar a los profesionales de herramientas y técnicas de gerencia que les permitan gestionar proyectos de manera efectiva, eficiente y con impacto social positivo.', 'https://drive.google.com/file/d/1RQ4z1ZlXC-0IqzxGB0bXA2To9hBGsT_z/view?usp=drive_link', 5760, 'intermedio', NULL, 'publicado', NULL, 70.00, 3, 'libre', true, NULL, '2026-07-28 17:17:51.099067+00', '2026-08-06 17:06:18.357085+00', NULL);
INSERT INTO public.cursos (id, titulo, slug, descripcion, objetivo, imagen_portada_url, duracion_estimada_min, nivel_dificultad, categoria_id, estado, autor_id, porcentaje_aprobacion, max_intentos, navegacion, es_diplomado, empresa_id, created_at, updated_at, deleted_at) VALUES ('6ace5efa-0afc-4c25-acc5-a4e255b2c5f8', 'DIPLOMADO EN CONSTRUCCIÓN DE PAZ', 'diplomado-en-construccion-de-paz', 'El curso de Construcción de Paz tiene como objetivo principal desarrollar enfoques educativos que promuevan la tolerancia, el diálogo intercultural, el respeto por los derechos humanos, la resolución no violenta de conflictos y la inclusión social. Los estudiantes adquirirán las habilidades necesarias para contribuir a la paz sostenible, abordando temas como la justicia transicional en Colombia, la memoria y reconciliación, y los desafíos del postconflicto. Este enfoque fomenta la creación de sociedades más equitativas y resilientes, con una fuerte orientación hacia la justicia, la verdad, la reparación y la no repetición.', 'Formar profesionales comprometidos con la promoción de la paz y la equidad en sus comunidades. Este programa busca dotar a los participantes de conocimientos teóricos y prácticos, herramientas metodológicas y habilidades necesarias para diseñar e implementar iniciativas efectivas que promuevan la convivencia pacífica, la justicia social y la equidad en diversos contextos.', NULL, 5760, 'intermedio', NULL, 'borrador', NULL, 70.00, 3, 'libre', true, NULL, '2026-07-30 15:51:18.27281+00', '2026-08-06 17:06:18.357085+00', NULL);
