INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4b6bba38-7429-4aa5-a40a-e5d1108a0d05', 'dc56a167-8990-4bc0-8e89-4023f15671d9', 'Solo la fecha del cambio', false, 'Incorrecto. Porque no corresponde al enfoque del tema.', 1, '2026-07-29 20:36:49.918073+00', '2026-07-29 20:36:49.918073+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8738902d-a1e6-45f0-a9de-ef4295044a01', 'dc56a167-8990-4bc0-8e89-4023f15671d9', 'Nada, porque ajustar es informal', false, 'Incorrecto. Porque no corresponde al enfoque del tema.', 2, '2026-07-29 20:36:49.918073+00', '2026-07-29 20:36:49.918073+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4ac6541c-0666-4bc1-805c-8bf6ef5ad67a', 'dc56a167-8990-4bc0-8e89-4023f15671d9', 'Únicamente la aprobación directiva', false, 'Incorrecto. Porque no corresponde al enfoque del tema.', 3, '2026-07-29 20:36:49.918073+00', '2026-07-29 20:36:49.918073+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b18db98d-0f96-45e9-97fb-26d16ddcbbf8', '116ad92b-532c-46bf-9510-ad54a8d6e635', 'El cambio reactivo responde tarde y con poca evidencia; el ajuste estratégico usa señales verificables y participación', true, 'Correcto. Porque responde al criterio central del tema.', 0, '2026-07-29 20:36:49.918073+00', '2026-07-29 20:36:49.918073+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2850c9e5-e66b-4308-8c4e-ea5bd37ef66c', '116ad92b-532c-46bf-9510-ad54a8d6e635', 'El cambio reactivo siempre es participativo', false, 'Incorrecto. Porque no corresponde al enfoque del tema.', 1, '2026-07-29 20:36:49.918073+00', '2026-07-29 20:36:49.918073+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('237173ce-ec32-4046-9f18-6cb7be191bf7', '116ad92b-532c-46bf-9510-ad54a8d6e635', 'El ajuste estratégico excluye análisis', false, 'Incorrecto. Porque no corresponde al enfoque del tema.', 2, '2026-07-29 20:36:49.918073+00', '2026-07-29 20:36:49.918073+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c5a260bb-c283-4fea-8569-0e0e26181abf', '116ad92b-532c-46bf-9510-ad54a8d6e635', 'No existe diferencia en gerencia social', false, 'Incorrecto. Porque no corresponde al enfoque del tema.', 3, '2026-07-29 20:36:49.918073+00', '2026-07-29 20:36:49.918073+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1444a41c-248e-417c-ac6c-a3a453daa82a', '33a04bb5-db5f-4b7a-90db-925c1c9fbb94', 'El conflicto siempre implica daño físico.', false, 'Incorrecto. Puede existir conflicto sin violencia cuando hay tensión, disputa o desacuerdo.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('478ef45d-f7ac-4340-88e4-29a1d39fbc3f', '33a04bb5-db5f-4b7a-90db-925c1c9fbb94', 'La violencia es una forma de escalamiento, mientras el conflicto puede tramitarse mediante diálogo.', true, 'Correcto. El conflicto es una relación de tensión que puede transformarse sin llegar a agresión.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2969afcc-5811-451e-88dd-8e0e44d51908', '33a04bb5-db5f-4b7a-90db-925c1c9fbb94', 'El conflicto desaparece cuando se niega públicamente.', false, 'Incorrecto. Negarlo suele aumentar desconfianza y deteriorar relaciones.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ef148972-5c2f-4ec5-8000-eba65308c5ba', '33a04bb5-db5f-4b7a-90db-925c1c9fbb94', 'La violencia es indispensable para obtener legitimidad.', false, 'Incorrecto. La legitimidad se construye con participación, transparencia y acuerdos verificables.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('eb90e1f3-7805-49dc-ac9c-d42e1a9b1f9f', '08b6560d-fc10-4a43-95d9-dbc60a3128fe', 'Diseñar una campaña de imagen antes de conocer las causas.', false, 'Incorrecto. La comunicación sin diagnóstico puede ser defensiva e insuficiente.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e0a613de-60d3-46bf-9fec-c07760b284e7', '08b6560d-fc10-4a43-95d9-dbc60a3128fe', 'Realizar un diagnóstico que reconozca hechos, percepciones, actores e impactos.', true, 'Correcto. Comprender la situación evita respuestas simplistas y permite construir rutas legítimas.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dab018ba-3621-48d5-a311-772869d4f34f', '08b6560d-fc10-4a43-95d9-dbc60a3128fe', 'Excluir a los actores más críticos para acelerar el proceso.', false, 'Incorrecto. Excluir voces críticas puede escalar la tensión.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c69810ae-13ce-4dc6-8f1d-21688a546317', '08b6560d-fc10-4a43-95d9-dbc60a3128fe', 'Ofrecer compensaciones sin analizar necesidades.', false, 'Incorrecto. Las compensaciones desconectadas de las causas no transforman el conflicto.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d0179cef-d299-4229-a67e-7ddb657b12df', '31b28662-4f2b-4a35-9298-df9232c9de7e', 'Permite identificar intereses, afectaciones, influencia y capacidad de mediación.', true, 'Correcto. El mapa ayuda a reconocer quiénes deben participar y por qué.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7bf10a67-2e5b-4aea-8b39-a3bea92ce644', '31b28662-4f2b-4a35-9298-df9232c9de7e', 'Sirve para reemplazar la participación comunitaria.', false, 'Incorrecto. El mapa orienta la participación, pero no la sustituye.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f1c89cbd-91b0-4acc-b1a9-9dd9d395b353', '31b28662-4f2b-4a35-9298-df9232c9de7e', 'Evita analizar necesidades profundas.', false, 'Incorrecto. Debe complementarse con intereses, necesidades y percepciones.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c10cbc5f-5b49-441b-a3cd-578047cc0e95', '31b28662-4f2b-4a35-9298-df9232c9de7e', 'Garantiza automáticamente el cierre del conflicto.', false, 'Incorrecto. Es una herramienta diagnóstica, no una solución por sí misma.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4ffe1928-ae6d-4022-88ae-b007ffa42a65', '5bc543ab-f4cf-4927-a8f5-76bc9eb1975f', 'Porque la legalidad ya no es necesaria.', false, 'Incorrecto. El cumplimiento legal sigue siendo indispensable.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2b10fda3-9cc9-41fd-bc9f-66bf60f003a2', '5bc543ab-f4cf-4927-a8f5-76bc9eb1975f', 'Porque una decisión puede ser legal y aun así ser percibida como injusta o excluyente.', true, 'Correcto. La legitimidad requiere reconocimiento, transparencia y aceptación social.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fe92f550-44de-43a8-afbf-3f3ac0ca1e13', '5bc543ab-f4cf-4927-a8f5-76bc9eb1975f', 'Porque la legitimidad depende solo de publicidad institucional.', false, 'Incorrecto. La legitimidad se sostiene con coherencia, participación y cumplimiento.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('30064b5e-df30-4370-b660-e4cf9db8b63c', '5bc543ab-f4cf-4927-a8f5-76bc9eb1975f', 'Porque la comunidad no debe conocer información técnica.', false, 'Incorrecto. La información comprensible fortalece legitimidad y confianza.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6242c860-e02c-4c21-b876-de8d63203921', 'c872a0a6-5fec-446b-8aff-40f34a020fee', 'Indagar intereses y necesidades detrás de la demanda.', false, 'Incorrecto. Esto es necesario para comprender causas profundas.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b80c125e-2ae9-4016-93f9-68566af54bbb', 'c872a0a6-5fec-446b-8aff-40f34a020fee', 'Crear espacios de diálogo con capacidad de incidencia.', false, 'Incorrecto. El diálogo sustantivo ayuda a tramitar el conflicto.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5a29a283-dcbe-4a60-8d9d-ca554b135557', 'c872a0a6-5fec-446b-8aff-40f34a020fee', 'Responder con donaciones sin atender la causa del desacuerdo.', true, 'Correcto. La donación aislada puede ocultar o agravar el problema central.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7ffa6696-b423-4557-a6a8-63bda0b6e481', 'c872a0a6-5fec-446b-8aff-40f34a020fee', 'Definir compromisos verificables y seguimiento.', false, 'Incorrecto. Esto favorece confianza y rendición de cuentas.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('df7e5eed-ad0c-4777-9102-7b62700bdeaf', '0a68bee2-10e1-4374-b31c-b0d5a0959e47', 'Gobernanza responsable.', true, 'Correcto. Esta área incorpora la responsabilidad social en decisiones, recursos y seguimiento.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('859675ef-4979-4611-a2c2-68b196f4c21d', '0a68bee2-10e1-4374-b31c-b0d5a0959e47', 'Donación ocasional.', false, 'Incorrecto. La donación no estructura la responsabilidad social en la organización.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2e26e86b-a4a4-4785-945f-40873160fc79', '0a68bee2-10e1-4374-b31c-b0d5a0959e47', 'Publicidad corporativa.', false, 'Incorrecto. La comunicación no reemplaza decisiones internas verificables.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8ef44ab6-a918-4585-befa-4cccf896effe', '0a68bee2-10e1-4374-b31c-b0d5a0959e47', 'Competencia comercial.', false, 'Incorrecto. La competencia puede relacionarse con prácticas justas, pero no define por sí sola la gobernanza responsable.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('499af04a-29b5-4a40-a05a-a91877c52f2d', '4c15a7a3-3b74-4f4e-ae7a-dd1c75d0c1c3', 'Porque eliminan toda posibilidad de desacuerdo comunitario.', false, 'Incorrecto. Pueden reducir riesgos, pero no eliminan todos los conflictos.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('eae504ce-b93a-4429-9d30-4fefcd532edb', '4c15a7a3-3b74-4f4e-ae7a-dd1c75d0c1c3', 'Porque abordan empleo digno, inclusión, seguridad, diálogo y condiciones contractuales.', true, 'Correcto. Las tensiones laborales pueden afectar legitimidad y relación territorial.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4c96f865-680b-49b0-bc3e-3d5dd14e4516', '4c15a7a3-3b74-4f4e-ae7a-dd1c75d0c1c3', 'Porque permiten prometer empleo sin criterios públicos.', false, 'Incorrecto. Las promesas ambiguas suelen generar frustración y desconfianza.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3d2643bc-9d37-4169-8986-9a566355dffb', '4c15a7a3-3b74-4f4e-ae7a-dd1c75d0c1c3', 'Porque reemplazan la gestión ambiental.', false, 'Incorrecto. Las áreas de RSE son interdependientes, no sustitutivas.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('59d06854-5b4b-42a8-86e4-31ab13287580', '5993a680-3123-4f20-b329-eea1b9f2ba90', 'Cumplir normas técnicas sin comunicar riesgos.', false, 'Incorrecto. El cumplimiento técnico no basta si no hay información comprensible y participación.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('826e26af-e94f-4517-a909-7e428fb5fbbc', '5993a680-3123-4f20-b329-eea1b9f2ba90', 'Reconocer que los impactos ecológicos también afectan salud, medios de vida y confianza.', true, 'Correcto. La gestión ambiental debe integrar medición, participación y disposición a ajustar prácticas.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dec87959-b4e8-49ce-9fd5-5cd606b98d2d', '5993a680-3123-4f20-b329-eea1b9f2ba90', 'Tratar las preocupaciones ambientales como percepciones sin valor.', false, 'Incorrecto. La percepción comunitaria aporta información social relevante.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3c6a5c40-ce8a-49b5-b54d-e90e520e3336', '5993a680-3123-4f20-b329-eea1b9f2ba90', 'Delegar toda responsabilidad ambiental a la comunidad.', false, 'Incorrecto. La empresa debe prevenir, mitigar y rendir cuentas por sus impactos.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('030a7205-7885-4e11-8765-446660ffea8c', 'f4618152-dd86-4bb5-abfc-a4d1e25c85bc', 'Que se fortalezcan automáticamente capacidades locales.', false, 'Incorrecto. El asistencialismo puede generar dependencia si no hay diagnóstico ni sostenibilidad.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('28e3429e-35c2-4e4c-9466-b468213a379d', 'f4618152-dd86-4bb5-abfc-a4d1e25c85bc', 'Que las acciones visibles no respondan a impactos materiales ni construyan capacidades sostenibles.', true, 'Correcto. La inversión social debe partir de diagnóstico participativo y evaluación.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a0f21665-f1e0-4eaa-b7a5-d3d82f025142', 'f4618152-dd86-4bb5-abfc-a4d1e25c85bc', 'Que se elimine la necesidad de alianzas.', false, 'Incorrecto. El desarrollo local responsable requiere corresponsabilidad y articulación institucional.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('13011e32-e301-46c8-8d31-63b6e09954eb', 'f4618152-dd86-4bb5-abfc-a4d1e25c85bc', 'Que desaparezcan los indicadores.', false, 'Incorrecto. Los indicadores son necesarios para evaluar resultados y aprendizajes.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('136e1b65-c149-40c0-9f54-2709ee59a8de', '02fc8153-2348-4faa-98dd-82d5ac4cf827', 'Transparencia, anticorrupción, compras responsables y relaciones equitativas con proveedores.', true, 'Correcto. Estas prácticas fortalecen confianza y reducen riesgos de exclusión o captura.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('008c5914-2804-4252-940d-3ec504556ada', '02fc8153-2348-4faa-98dd-82d5ac4cf827', 'Únicamente actividades de voluntariado.', false, 'Incorrecto. El voluntariado no agota la ética en la operación y cadena de valor.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('14697e07-c90a-45bb-bb97-c5868ae9dba2', '02fc8153-2348-4faa-98dd-82d5ac4cf827', 'Solo campañas ambientales.', false, 'Incorrecto. La dimensión ambiental es otra área interconectada de la RSE.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('83f91448-f1c2-4724-8d4f-014d50de474e', '02fc8153-2348-4faa-98dd-82d5ac4cf827', 'Promesas de inversión sin trazabilidad.', false, 'Incorrecto. La trazabilidad es indispensable para evitar conflictos por incumplimiento.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('97e08a68-77a1-458f-af4c-4f376cf58d9b', 'dcd82757-e01a-4a3a-b543-9461f4e0ca47', 'No confundirse con filantropía ni comunicación reputacional.', true, 'Correcto. La RSE exige gestión de impactos, coherencia, participación y evidencia.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8eeccfee-6e35-405b-bc0c-e5af16d955c8', 'dcd82757-e01a-4a3a-b543-9461f4e0ca47', 'Limitarse a campañas de marca.', false, 'Incorrecto. Esto reduce su alcance estratégico y puede debilitar legitimidad.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9285e6a2-a5d5-4358-a387-6a955f4d3608', 'dcd82757-e01a-4a3a-b543-9461f4e0ca47', 'Sustituir todas las obligaciones del Estado.', false, 'Incorrecto. La empresa no reemplaza al Estado, aunque debe actuar con diligencia.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fe4e5305-35f1-4c9c-b6c4-e66d391559dd', 'dcd82757-e01a-4a3a-b543-9461f4e0ca47', 'Evitar la medición para no generar tensiones.', false, 'Incorrecto. La medición es clave para aprendizaje y rendición de cuentas.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('bb842bc4-a58e-4735-93ac-95c718365736', '72c7f0c6-c1ce-40de-8bbd-7bb3c3702b92', 'La correspondencia verificable entre compromisos declarados y acciones reales.', true, 'Correcto. La legitimidad depende de evidencias observables y prácticas consistentes.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2b0e14ca-bde8-4635-9dff-988f06016100', '72c7f0c6-c1ce-40de-8bbd-7bb3c3702b92', 'La capacidad de ocultar fallas mediante informes extensos.', false, 'Incorrecto. Los informes no corrigen prácticas deficientes.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e9f67235-c075-44d1-8f77-b1769060c6c0', '72c7f0c6-c1ce-40de-8bbd-7bb3c3702b92', 'La separación absoluta entre operación y RSE.', false, 'Incorrecto. La RSE debe integrarse al modelo de negocio y a la operación.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9d3e3df8-03ae-47a7-b26a-c818c342a987', '72c7f0c6-c1ce-40de-8bbd-7bb3c3702b92', 'La prioridad exclusiva de reputación externa.', false, 'Incorrecto. La reputación debe basarse en evidencia y responsabilidad real.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8e3eaf4c-453a-419c-a747-efc1ae7d3126', 'd772a267-7f73-4cf6-8737-34667e1a4ab6', 'Porque obliga a priorizar asuntos relevantes según impactos y grupos de interés.', true, 'Correcto. Ayuda a enfocar recursos en temas críticos y no solo visibles.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c652d4b9-401c-4222-bcc3-df41f19b2a6d', 'd772a267-7f73-4cf6-8737-34667e1a4ab6', 'Porque permite elegir temas cómodos para la alta dirección.', false, 'Incorrecto. Definir materialidad sin participación puede invisibilizar riesgos.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9008f8b3-c4df-4047-b44e-ec39f66d85b1', 'd772a267-7f73-4cf6-8737-34667e1a4ab6', 'Porque elimina la necesidad de diálogo territorial.', false, 'Incorrecto. La materialidad requiere consulta, datos y revisión de quejas.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('47243d63-555a-4fa6-889d-0493189ef318', 'd772a267-7f73-4cf6-8737-34667e1a4ab6', 'Porque convierte toda acción en impacto social.', false, 'Incorrecto. La materialidad orienta qué medir, pero no reemplaza la evaluación.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('23749cab-eae8-4184-b30e-16459a40cca5', 'abc1b3ea-265a-42f9-8b7e-2c3c79fcd6df', 'Contar actividades sin analizar cambios.', false, 'Incorrecto. Actividades no equivalen a resultados o impactos.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('44a63440-7ca2-4448-855b-718478d00cd4', 'abc1b3ea-265a-42f9-8b7e-2c3c79fcd6df', 'Usar líneas base, indicadores, fuentes de verificación y participación de actores.', true, 'Correcto. La evidencia debe mostrar qué cambió, para quién y con qué límites.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('facd239a-d150-4112-8264-d58242fa7f32', 'abc1b3ea-265a-42f9-8b7e-2c3c79fcd6df', 'Reportar únicamente logros favorables.', false, 'Incorrecto. La rendición responsable incluye límites, errores y ajustes.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('83c625ef-a548-48bb-b276-1ef139a81df4', 'abc1b3ea-265a-42f9-8b7e-2c3c79fcd6df', 'Evitar datos cualitativos.', false, 'Incorrecto. Las percepciones y narrativas ayudan a comprender legitimidad y confianza.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ade93fcd-a588-4b4f-b8ad-66ea617aa365', 'a5dcb137-d20e-4e3b-8fd4-e19b60ee5c22', 'Que dependa de un área aislada sin poder de decisión.', true, 'Correcto. Sin responsabilidades, presupuesto y alineación, la RSE pierde coherencia operativa.', 0, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5bae3a71-06e4-49b0-a15d-ff74717adf54', 'a5dcb137-d20e-4e3b-8fd4-e19b60ee5c22', 'Que mejore automáticamente las compras responsables.', false, 'Incorrecto. La mejora requiere decisiones y mecanismos específicos.', 1, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('76b922df-a649-41d7-bfb1-1b2f072d3425', 'a5dcb137-d20e-4e3b-8fd4-e19b60ee5c22', 'Que elimine la necesidad de indicadores.', false, 'Incorrecto. La gobernanza debe incluir seguimiento y evaluación.', 2, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('eb39b40a-9b09-4957-a157-a1e694bab17e', 'a5dcb137-d20e-4e3b-8fd4-e19b60ee5c22', 'Que la comunidad asuma toda la responsabilidad.', false, 'Incorrecto. La empresa debe definir sus responsabilidades internas.', 3, '2026-07-29 20:37:18.018085+00', '2026-07-29 20:37:18.018085+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('33513bb3-7dd8-4387-9193-129de3d8ac6f', '097208b4-c677-42cd-999f-e424bf2d079c', 'Solo como actor económico sin efectos sociales.', false, 'Incorrecto. La empresa también modifica expectativas, recursos, relaciones y confianza.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ad4cbdb1-d05e-493e-8359-ad6bc18fa6b5', '097208b4-c677-42cd-999f-e424bf2d079c', 'Como actor social situado que incide en comunidad, territorio e instituciones.', true, 'Correcto. Esta lectura permite analizar impactos, riesgos y responsabilidades públicas.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8aac6a71-6e20-4c2c-8778-845b63c2cf5c', '097208b4-c677-42cd-999f-e424bf2d079c', 'Como sustituto completo del Estado.', false, 'Incorrecto. La empresa puede cooperar, pero no reemplaza responsabilidades estatales.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4e60698c-7e0a-427b-8ea1-1179e5d242d0', '097208b4-c677-42cd-999f-e424bf2d079c', 'Como beneficiaria pasiva de decisiones comunitarias.', false, 'Incorrecto. La empresa toma decisiones que también producen efectos sociales.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dcde0813-fdbd-4d39-a8a8-4574d11f455a', '7ada81b0-71dc-4d05-b49d-96222251b85d', 'Distribución desigual de beneficios y cargas, falta de reconocimiento o información insuficiente.', true, 'Correcto. Estas dimensiones afectan justicia, confianza y legitimidad.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7c20dc57-451b-49ab-beae-f90e09c9419e', '7ada81b0-71dc-4d05-b49d-96222251b85d', 'Únicamente la falta de publicidad corporativa.', false, 'Incorrecto. La comunicación importa, pero los conflictos tienen causas más profundas.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f56a82e6-2e11-4158-9a0b-ffe197fc1c96', '7ada81b0-71dc-4d05-b49d-96222251b85d', 'Solo la ausencia de permisos legales.', false, 'Incorrecto. Puede existir permiso legal y conflicto social por impactos o legitimidad.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dacb1c3b-114e-4668-a3af-3af77d6224ed', '7ada81b0-71dc-4d05-b49d-96222251b85d', 'Exclusivamente diferencias personales entre líderes.', false, 'Incorrecto. También intervienen estructuras, derechos, impactos y expectativas.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a476850b-2830-4b42-b54e-1f69af088c74', 'd26645db-36e3-4da0-9a82-24e3ad493f9b', 'Identificar, prevenir, mitigar y rendir cuentas sobre impactos sociales y ambientales.', true, 'Correcto. Convierte la responsabilidad social en un sistema de gestión con evidencias.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4757c884-b486-4dea-b511-dca361ca4912', 'd26645db-36e3-4da0-9a82-24e3ad493f9b', 'Responder únicamente después de una protesta.', false, 'Incorrecto. La debida diligencia es preventiva y continua.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5166e5b5-4c44-4648-8421-23e1eaeae014', 'd26645db-36e3-4da0-9a82-24e3ad493f9b', 'Reducir la participación a socialización de resultados.', false, 'Incorrecto. La participación debe permitir incidencia y seguimiento.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('15b904e5-276c-4936-a88d-e58ec08865c4', 'd26645db-36e3-4da0-9a82-24e3ad493f9b', 'Delegar impactos en terceros sin seguimiento.', false, 'Incorrecto. Las relaciones comerciales y cadenas de valor también pueden generar responsabilidades.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1c94daee-12f4-43d0-a9bc-ad4f6d44f159', '192293c4-2236-4c6c-9075-0760877353c7', 'Silenciar inconformidades para evitar reputación negativa.', false, 'Incorrecto. Silenciar quejas incrementa desconfianza.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b7f8f2e9-ef60-45c5-b0ab-8592679fc90c', '192293c4-2236-4c6c-9075-0760877353c7', 'Canalizar preocupaciones, registrar compromisos y generar aprendizaje organizacional.', true, 'Correcto. Un mecanismo accesible permite anticipar riesgos y corregir prácticas.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f3ec720f-ce0b-4a86-9a4b-512ac63f738c', '192293c4-2236-4c6c-9075-0760877353c7', 'Reemplazar las obligaciones legales.', false, 'Incorrecto. Complementan, pero no sustituyen la normatividad.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6fa7dd24-22de-49c6-bc1e-7371a3702f4b', '192293c4-2236-4c6c-9075-0760877353c7', 'Cerrar conflictos sin investigar causas.', false, 'Incorrecto. Deben vincularse con análisis, respuesta y seguimiento.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9ad0a72c-ed90-4304-9839-7ee01450a623', 'e0b09de2-bb72-49cd-ac34-5fd0257439b4', 'Eliminar toda crítica comunitaria.', false, 'Incorrecto. La transformación no busca silenciar, sino tramitar desacuerdos legítimos.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a9929460-f50b-4452-988e-2362fa15e125', 'e0b09de2-bb72-49cd-ac34-5fd0257439b4', 'Convertir tensiones en oportunidades de diálogo, reparación, aprendizaje y acuerdos.', true, 'Correcto. El enfoque modifica condiciones que reproducen la tensión.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dc8426a0-940d-4f0b-97ef-2bdb23e938e6', 'e0b09de2-bb72-49cd-ac34-5fd0257439b4', 'Imponer acuerdos rápidos para reanudar operaciones.', false, 'Incorrecto. La imposición puede reactivar el conflicto.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('887a439a-9915-473c-9d7a-9f740dbb7043', 'e0b09de2-bb72-49cd-ac34-5fd0257439b4', 'Reemplazar la participación por asistencia económica.', false, 'Incorrecto. La asistencia no sustituye reconocimiento, diálogo y cambios de práctica.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1ac6619e-0abc-4fbc-914f-c6c6bf099a54', '3412afe6-a8dc-4af2-bb1a-b87008bd1d3b', 'Solo una molestia temporal sin consecuencias futuras.', false, 'Incorrecto. Puede afectar operación, reputación, costos, legitimidad y relaciones.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('19e4a838-2914-42e7-8838-fe22e169b3fb', '3412afe6-a8dc-4af2-bb1a-b87008bd1d3b', 'Deterioro de continuidad, reputación, confianza, costos y capacidad de crear valor social.', true, 'Correcto. Los conflictos generan impactos encadenados sobre la sostenibilidad empresarial.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0575efd0-66ea-4f62-b857-51ad89c92da3', '3412afe6-a8dc-4af2-bb1a-b87008bd1d3b', 'Exclusivamente aumento de ventas por visibilidad.', false, 'Incorrecto. La visibilidad negativa puede producir pérdida de confianza y sanciones.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('73bf9ab8-b5d4-4c00-abc1-6f8b5c2e85a0', '3412afe6-a8dc-4af2-bb1a-b87008bd1d3b', 'Ningún efecto si hay permisos legales vigentes.', false, 'Incorrecto. La legalidad no evita costos sociales y reputacionales.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4ba55111-4959-4935-8600-890b59af68fd', '7ed8060b-da6d-4745-afcf-1c2c6262ca1f', 'La probabilidad de que una decisión genere tensiones que afecten legitimidad o continuidad.', true, 'Correcto. Permite anticipar conflictos por impactos, expectativas o derechos.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6d354864-7d1e-4e94-be9f-aad42b9c5033', '7ed8060b-da6d-4745-afcf-1c2c6262ca1f', 'Una categoría idéntica al riesgo financiero.', false, 'Incorrecto. Se relaciona con lo financiero, pero incluye confianza, actores e impactos sociales.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5d089209-0158-45b2-9a67-6042f593eb0b', '7ed8060b-da6d-4745-afcf-1c2c6262ca1f', 'Una amenaza que solo depende de la comunidad.', false, 'Incorrecto. También surge de decisiones empresariales, omisiones o fallas de comunicación.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('70f15595-1e82-4b97-bfc9-0c903e65078d', '7ed8060b-da6d-4745-afcf-1c2c6262ca1f', 'Un asunto que se resuelve solo con seguridad privada.', false, 'Incorrecto. La seguridad no gestiona causas sociales ni legitimidad.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c6af035f-7cd4-46a0-bd01-471ff16029c0', '5584fc57-0a25-4231-ae45-01ad8222f291', 'Porque la aceptación comunitaria influye en continuidad y legitimidad.', true, 'Correcto. Un proyecto con permisos puede enfrentar resistencia si pierde confianza social.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0fe2fd95-df14-4f9c-91b7-e83fada32df1', '5584fc57-0a25-4231-ae45-01ad8222f291', 'Porque elimina automáticamente los contratos firmados.', false, 'Incorrecto. No elimina por sí misma contratos, pero puede generar bloqueos y crisis.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('19f2e129-3d70-485d-9543-acfb51d71feb', '5584fc57-0a25-4231-ae45-01ad8222f291', 'Porque reemplaza todo estudio técnico.', false, 'Incorrecto. La licencia social complementa, no sustituye, análisis técnico y legal.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1ba06f53-ea28-482e-a65c-0ed854838ddc', '5584fc57-0a25-4231-ae45-01ad8222f291', 'Porque depende solo de donaciones.', false, 'Incorrecto. La aceptación se construye con cumplimiento, diálogo y coherencia.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6a1e9f30-fee1-40d7-b7f6-6846bb06e705', 'e6ef8d93-382a-4a59-bf5b-f5e328f07286', 'Incluir retrasos y asesorías legales.', false, 'Incorrecto. Estos son costos relevantes.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('25fa2427-7d4d-47b0-b192-292d07728103', 'e6ef8d93-382a-4a59-bf5b-f5e328f07286', 'Omitir pérdidas indirectas como confianza, reputación y relaciones futuras.', true, 'Correcto. El costo no se limita a gastos visibles o inmediatos.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('98fded65-1024-4af2-8e32-8e7fa80baddf', 'e6ef8d93-382a-4a59-bf5b-f5e328f07286', 'Considerar la continuidad operativa.', false, 'Incorrecto. La continuidad es una dimensión afectada por el conflicto.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9f9347a0-4e10-4124-a72b-18a67f9b0d24', 'e6ef8d93-382a-4a59-bf5b-f5e328f07286', 'Analizar causas del bloqueo.', false, 'Incorrecto. Analizar causas ayuda a prevenir nuevos costos.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b9fdc9ec-ad43-4317-8031-4f184b1417e5', 'bfd352ef-4636-402c-8de9-4fa42c38b2b6', 'El síntoma es la manifestación visible; la causa puede estar en impactos, promesas o falta de participación.', true, 'Correcto. Distinguir ambos niveles evita respuestas superficiales.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7bf346c6-f1eb-401b-881b-d151f77ed8b7', 'bfd352ef-4636-402c-8de9-4fa42c38b2b6', 'Ambos significan exactamente lo mismo.', false, 'Incorrecto. Confundirlos impide transformar el conflicto.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('51e94227-0d18-4552-adb4-b1d2b287d594', 'bfd352ef-4636-402c-8de9-4fa42c38b2b6', 'La causa siempre es la protesta pública.', false, 'Incorrecto. La protesta suele ser síntoma de tensiones previas.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e1bf79c6-193d-4768-bdb3-f7e1c5a0acca', 'bfd352ef-4636-402c-8de9-4fa42c38b2b6', 'El síntoma debe gestionarse sin revisar prácticas internas.', false, 'Incorrecto. Atender solo el síntoma puede reabrir la crisis.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('71939370-17f4-4696-ac70-1411a56702dd', '9edebdc0-34eb-4d11-94f5-1537e481d543', 'La preventiva lee señales tempranas, actores y causas antes de la crisis.', true, 'Correcto. Permite actuar con diagnóstico, diálogo y medidas proporcionales.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e90e77c4-4482-4cae-bf2d-636ed7e0ac64', '9edebdc0-34eb-4d11-94f5-1537e481d543', 'La preventiva niega los impactos para evitar responsabilidades.', false, 'Incorrecto. Negar impactos deteriora confianza.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b64fa6cf-18ef-405d-9cc7-e1f5f9558ca8', '9edebdc0-34eb-4d11-94f5-1537e481d543', 'La reacción defensiva siempre transforma el conflicto.', false, 'Incorrecto. La defensa sin escucha suele escalar tensiones.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('969187d7-e738-491c-84e3-4af08901c6d7', '9edebdc0-34eb-4d11-94f5-1537e481d543', 'La prevención elimina la necesidad de seguimiento.', false, 'Incorrecto. El seguimiento es parte central de la prevención responsable.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('bee0c152-8ea7-4737-8ede-2cef480ce564', '97e2ae97-b105-4c8c-a7f8-60dcb7bd8106', 'La imposición de una decisión por parte de la empresa.', false, 'Incorrecto. La mediación facilita comunicación; no impone soluciones.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fca9f560-fa4f-4edf-8b80-1473bcec58d1', '97e2ae97-b105-4c8c-a7f8-60dcb7bd8106', 'La intervención de un tercero legítimo e imparcial que ayuda a construir condiciones de acuerdo.', true, 'Correcto. Es útil cuando existe bloqueo, desconfianza o asimetría.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('87f7e247-4a06-49e2-9c88-ba625905cfef', '97e2ae97-b105-4c8c-a7f8-60dcb7bd8106', 'Un mecanismo para evitar la participación comunitaria.', false, 'Incorrecto. La mediación debe ampliar comunicación y reconocimiento.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4c495115-2e07-404d-907e-ab008e8522d3', '97e2ae97-b105-4c8c-a7f8-60dcb7bd8106', 'Una campaña para mejorar imagen pública.', false, 'Incorrecto. Su finalidad es facilitar diálogo y acuerdos, no propaganda.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0a2d8f00-4add-4cf1-87a5-916141ec91ab', 'eaf28145-af87-4894-9e33-a4f2e9e9c340', 'La búsqueda de soluciones basadas en intereses comunes y criterios verificables.', true, 'Correcto. Reduce la lógica de vencedores y vencidos.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('53a98e66-d8c2-4332-8843-4aa6f0e2b1d3', 'eaf28145-af87-4894-9e33-a4f2e9e9c340', 'La imposición de posiciones rígidas.', false, 'Incorrecto. La negociación colaborativa se centra en intereses, no en imposiciones.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e6189340-8abf-41d2-a97c-79ea6f5853ba', 'eaf28145-af87-4894-9e33-a4f2e9e9c340', 'La compra rápida del silencio comunitario.', false, 'Incorrecto. Negociar compensaciones sin causas puede reactivar el conflicto.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3e0fb067-a1ec-432a-b175-b59ad951428b', 'eaf28145-af87-4894-9e33-a4f2e9e9c340', 'La exclusión de información relevante.', false, 'Incorrecto. La transparencia fortalece acuerdos legítimos.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ef73128a-5d3f-42ad-935e-884c3b8f7339', '87dfa9bc-5cae-473d-9ead-0cdf295a2051', 'Porque requiere verificación de cumplimiento, comunicación, aprendizaje y ajuste.', true, 'Correcto. Sin seguimiento, el acuerdo puede convertirse en promesa frágil.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2ea784d7-169e-4539-b987-140e8c8775cf', '87dfa9bc-5cae-473d-9ead-0cdf295a2051', 'Porque la firma no tiene ninguna utilidad.', false, 'Incorrecto. La firma es importante, pero insuficiente sin implementación.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7b1c20d6-07fe-4c25-a1a6-754312f8ef94', '87dfa9bc-5cae-473d-9ead-0cdf295a2051', 'Porque debe mantenerse en secreto.', false, 'Incorrecto. La trazabilidad y comunicación fortalecen confianza.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('12350d1f-7aa5-4bb8-98a0-202e020923ed', '87dfa9bc-5cae-473d-9ead-0cdf295a2051', 'Porque la empresa debe cambiarlo unilateralmente.', false, 'Incorrecto. Los ajustes deben basarse en evidencia y diálogo.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('44ea8e5b-8d79-47c0-b3fa-502954115e7b', '7246d49e-a8d0-4fa5-9312-064b0cf84de1', 'Escuchar posiciones diversas.', false, 'Incorrecto. La escucha es necesaria para comprender intereses y necesidades.', 0, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('024e6c97-470a-4ef3-ae8c-f35a6d2988fc', '7246d49e-a8d0-4fa5-9312-064b0cf84de1', 'Usarlo como socialización sin posibilidad real de incidencia.', true, 'Correcto. El diálogo no debe legitimar decisiones ya cerradas sin participación.', 1, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('517ed80d-0908-4885-8faf-d0b149c6c080', '7246d49e-a8d0-4fa5-9312-064b0cf84de1', 'Registrar acuerdos y responsables.', false, 'Incorrecto. El registro fortalece seguimiento y rendición de cuentas.', 2, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('409009b5-5a11-4689-b94f-8f83633d20cf', '7246d49e-a8d0-4fa5-9312-064b0cf84de1', 'Incluir mediadores legítimos cuando hay desconfianza.', false, 'Incorrecto. La mediación puede facilitar comunicación y acuerdos.', 3, '2026-07-29 20:37:56.142077+00', '2026-07-29 20:37:56.142077+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4857c40e-0e22-4c6e-9b62-e0a049218a2d', '02561322-032c-41e1-96c4-6f92f36ad5f6', 'Medir observa señales; evaluar interpreta valor, pertinencia, eficacia y aprendizaje.', true, 'Correcto. Ambas dimensiones se complementan para tomar decisiones responsables.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('06abe403-adb2-4838-a3a1-af8f77c0dd7f', '02561322-032c-41e1-96c4-6f92f36ad5f6', 'Medir y evaluar son lo mismo en todos los casos.', false, 'Incorrecto. La medición produce datos; la evaluación emite juicios argumentados.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ec03ec02-8b80-4b24-8aca-ff401a756114', '02561322-032c-41e1-96c4-6f92f36ad5f6', 'Evaluar consiste solo en contar beneficiarios.', false, 'Incorrecto. Contar beneficiarios es insuficiente para interpretar impacto.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('67f1ffbf-c0e4-4c63-bbd6-7e2a56b2728f', '02561322-032c-41e1-96c4-6f92f36ad5f6', 'Medir evita la participación comunitaria.', false, 'Incorrecto. La medición puede y debe incorporar grupos de interés.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3b925bf0-695e-43d8-a9db-eaa9032466a0', 'b9a6c058-9c04-4a48-89f6-2b2a82d8a7fd', 'La descripción inicial de la situación antes de implementar la intervención.', true, 'Correcto. Permite comparar cambios y valorar avances con rigor.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('021fd57e-69f1-4b77-bbbd-586543894b61', 'b9a6c058-9c04-4a48-89f6-2b2a82d8a7fd', 'Un informe final elaborado después de comunicar resultados.', false, 'Incorrecto. La línea base debe construirse antes o al inicio de la intervención.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5bb1c561-1868-4db8-87bf-e44ed692512b', 'b9a6c058-9c04-4a48-89f6-2b2a82d8a7fd', 'Una lista de actividades realizadas.', false, 'Incorrecto. Las actividades no describen el punto de partida social.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('cb5f8fe2-6e88-4bf8-b349-797072d54323', 'b9a6c058-9c04-4a48-89f6-2b2a82d8a7fd', 'Una opinión directiva sin datos.', false, 'Incorrecto. Requiere fuentes verificables y lectura contextual.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('945139b7-89da-4df3-830a-242c24f086e6', 'e6140d68-90ce-413f-8bce-f67e50f8fdf7', 'Explica cómo y por qué una intervención espera producir resultados.', true, 'Correcto. Conecta recursos, actividades, productos, resultados, supuestos y riesgos.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1ca6fece-8361-4f01-8d80-55736b1ec03f', 'e6140d68-90ce-413f-8bce-f67e50f8fdf7', 'Elimina la necesidad de indicadores.', false, 'Incorrecto. La teoría de cambio orienta indicadores pertinentes.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('67d5504a-0777-4c40-82b4-233cb086bb85', 'e6140d68-90ce-413f-8bce-f67e50f8fdf7', 'Demuestra impacto automáticamente.', false, 'Incorrecto. Es una hipótesis que debe verificarse con evidencia.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2283968a-1ebe-4918-894e-e930d1c3cd26', 'e6140d68-90ce-413f-8bce-f67e50f8fdf7', 'Solo sirve para elaborar piezas gráficas.', false, 'Incorrecto. Puede graficarse, pero su función es ordenar la lógica evaluativa.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3bc92ceb-4387-41e7-bd04-ac6a30e5dc4e', '61ad666a-3c84-4d44-b148-112d8d872252', 'Número de reuniones presentado como participación efectiva sin más análisis.', false, 'Incorrecto. La asistencia no prueba incidencia ni calidad del diálogo.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('784489a3-76dc-40a9-9730-86c1bc0b61dc', '61ad666a-3c84-4d44-b148-112d8d872252', 'Porcentaje de proveedores locales fortalecidos y percepción de confianza en el mecanismo de compras.', true, 'Correcto. Combina señales verificables sobre resultados y legitimidad.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3ea78c55-7967-4d00-83d4-b5846a279b2e', '61ad666a-3c84-4d44-b148-112d8d872252', 'Monto invertido sin relación con resultados.', false, 'Incorrecto. La inversión no demuestra transformación por sí sola.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c65cb022-cd94-4238-8937-3836bb2356c6', '61ad666a-3c84-4d44-b148-112d8d872252', 'Cantidad de publicaciones en redes corporativas.', false, 'Incorrecto. La comunicación no equivale a cambio social.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('11d71ab3-c329-4f80-ad09-89279095f9c7', '824c9b17-8056-48f2-a556-3291f11052aa', 'Porque implica información comprensible, diálogo, respuesta a preguntas y correcciones.', true, 'Correcto. La rendición debe volver a los actores afectados y abrir aprendizaje.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9f3a6662-4617-4568-8e49-aa0c576743c8', '824c9b17-8056-48f2-a556-3291f11052aa', 'Porque los informes no tienen ninguna utilidad.', false, 'Incorrecto. Pueden ser útiles si son claros, verificables y dialogados.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d3ebc403-0fd4-48fe-b99e-5a19a28fb9f6', '824c9b17-8056-48f2-a556-3291f11052aa', 'Porque debe ocultar indicadores no cumplidos.', false, 'Incorrecto. Ocultar límites debilita confianza.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b466111d-88a4-4730-b082-4565eff60d52', '824c9b17-8056-48f2-a556-3291f11052aa', 'Porque solo interesa a la alta dirección.', false, 'Incorrecto. Los grupos de interés tienen derecho a información y respuesta.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('66888da1-ac87-4957-9cdb-f9e37df3ee4d', '349ec0da-11ed-413c-baa9-6c8ee5667346', 'Pertinencia.', true, 'Correcto. La pertinencia examina la relación entre intervención, problema y contexto.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('20cb6096-ab3e-40d0-9806-b8a825a46b8a', '349ec0da-11ed-413c-baa9-6c8ee5667346', 'Eficiencia.', false, 'Incorrecto. La eficiencia analiza relación entre recursos y productos.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('797ce20c-5ae7-4f03-85a7-e82272186d48', '349ec0da-11ed-413c-baa9-6c8ee5667346', 'Publicidad.', false, 'Incorrecto. La publicidad no es un criterio evaluativo suficiente.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a3a1bd29-445b-4a0f-b3c9-f92cdc1c1907', '349ec0da-11ed-413c-baa9-6c8ee5667346', 'Rotación.', false, 'Incorrecto. La rotación puede ser un dato organizacional, pero no define pertinencia.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f90a4ab4-8603-4592-b5e4-6c5ef231a812', 'ab08f61e-4c39-4ad6-86db-6f35111a18d2', 'Generar reportes extensos pero poco pertinentes para los actores afectados.', true, 'Correcto. La medición debe responder a materialidad, impactos y participación.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9d47f826-8a53-4397-af7a-6c1e3e5845dd', 'ab08f61e-4c39-4ad6-86db-6f35111a18d2', 'Mejorar automáticamente el aprendizaje.', false, 'Incorrecto. Indicadores sesgados pueden impedir reconocer problemas reales.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('aa2001bd-87b0-46f8-a236-0ef7bd2cc122', 'ab08f61e-4c39-4ad6-86db-6f35111a18d2', 'Aumentar la transparencia por sí misma.', false, 'Incorrecto. La transparencia depende de comunicar información relevante y completa.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('65163a33-19d6-4bcc-b47d-863c2d5d2c0d', 'ab08f61e-4c39-4ad6-86db-6f35111a18d2', 'Eliminar la necesidad de evaluación.', false, 'Incorrecto. La evaluación sigue siendo necesaria para interpretar datos.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('313d62b0-67e2-4f41-8763-5a54f312f2e5', '1c87b4ec-98fa-47af-9df0-e280296267a7', 'Archivar informes sin decisiones.', false, 'Incorrecto. El almacenamiento no modifica prácticas.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('07fa0a5c-7490-4d5a-b3ac-ce904425709d', '1c87b4ec-98fa-47af-9df0-e280296267a7', 'Usar evidencia y retroalimentación para ajustar programas, recursos y compromisos.', true, 'Correcto. La organización aprende cuando cambia su actuación según resultados.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0d9e2b4f-c636-4221-b120-56d477fef4b2', '1c87b4ec-98fa-47af-9df0-e280296267a7', 'Reportar únicamente resultados positivos.', false, 'Incorrecto. El aprendizaje requiere reconocer límites y errores.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ffb39212-0fe5-4624-bcbd-ee142f33ed32', '1c87b4ec-98fa-47af-9df0-e280296267a7', 'Reducir la evaluación al área de comunicaciones.', false, 'Incorrecto. La evaluación debe incidir en decisiones estratégicas y operativas.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8611fd1a-95dc-4f4f-8924-2477370a45dd', 'da685271-57a1-439e-91ad-0fe59ed02e4e', 'Una acción adaptativa construida con señales del entorno, evidencia y diálogo con actores afectados.', true, 'Correcto. Ajusta prioridades sin perder coherencia institucional.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d534cb83-f4f0-4d39-950c-56b5a4a70504', 'da685271-57a1-439e-91ad-0fe59ed02e4e', 'Una improvisación para apagar crisis.', false, 'Incorrecto. La emergencia responsable requiere método y trazabilidad.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1f05ce06-b00b-442a-9076-f382e8a9b4ce', 'da685271-57a1-439e-91ad-0fe59ed02e4e', 'Un programa fijo que no cambia aunque cambie el territorio.', false, 'Incorrecto. Las estrategias emergentes se ajustan ante nuevos riesgos y aprendizajes.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('285c32ed-53e3-45c5-bebe-f2c77de6fb36', 'da685271-57a1-439e-91ad-0fe59ed02e4e', 'Una donación aislada de corto plazo.', false, 'Incorrecto. No se reduce a asistencia, sino a gestión estratégica de impactos.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e5ad469c-64cd-4a79-96ea-27d945ecbe67', '8134b2ab-1e93-462d-ad90-329f3e2dc5d1', 'Soluciones nuevas o mejoradas construidas con actores locales y adaptadas al contexto.', true, 'Correcto. La innovación social debe ser apropiable, justa y pertinente para el territorio.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e61d9568-9d42-4c6a-b187-378cbfd943fa', '8134b2ab-1e93-462d-ad90-329f3e2dc5d1', 'Uso de tecnología aunque no responda a necesidades comunitarias.', false, 'Incorrecto. La tecnología sin apropiación puede fracasar.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5b53046b-e094-4506-b1e3-f9768511ade6', '8134b2ab-1e93-462d-ad90-329f3e2dc5d1', 'Duplicación de programas sin participación.', false, 'Incorrecto. La innovación requiere co-creación y lectura contextual.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('bb7c633d-a519-40cb-849d-925462b21d6d', '8134b2ab-1e93-462d-ad90-329f3e2dc5d1', 'Sustitución de responsabilidades públicas por acciones empresariales.', false, 'Incorrecto. Las alianzas deben respetar roles y corresponsabilidad.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('45aee407-52e2-425f-8b1d-7e5f8a638c10', '2e0de60c-a296-4039-9334-4fad02700971', 'Coordinar empresas, comunidades, Estado y otros actores en decisiones sobre problemas comunes.', true, 'Correcto. Permite distribuir responsabilidades y construir legitimidad.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b9bbb093-47dc-463c-8460-5a35f98826df', '2e0de60c-a296-4039-9334-4fad02700971', 'Concentrar todas las decisiones en la empresa.', false, 'Incorrecto. La colaboración requiere reglas, información compartida e incidencia.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('99664f2d-f09f-4731-a6b6-8cdb3308a8e6', '2e0de60c-a296-4039-9334-4fad02700971', 'Evitar desacuerdos mediante reuniones formales.', false, 'Incorrecto. Los desacuerdos pueden permanecer, pero se tramitan con reglas claras.', 2, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0082354b-9c78-49f4-bb22-f871c6d8efac', '2e0de60c-a296-4039-9334-4fad02700971', 'Reemplazar evidencia por opiniones de autoridad.', false, 'Incorrecto. La gobernanza colaborativa necesita datos, seguimiento y deliberación.', 3, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0576aef3-9c8c-4177-8df1-9d35fab71e5c', 'f1d33446-b685-41d1-9c71-438bd2a66436', 'Priorizar asuntos relevantes sabiendo que pueden cambiar con el tiempo.', true, 'Correcto. La relevancia depende de impactos, actores, riesgos y contexto.', 0, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6ce73eee-223f-4e46-bb38-806fd565a2bc', 'f1d33446-b685-41d1-9c71-438bd2a66436', 'Mantener prioridades fijas aunque aparezcan nuevos impactos.', false, 'Incorrecto. La dinámica exige revisión periódica.', 1, '2026-07-29 20:38:35.277794+00', '2026-07-29 20:38:35.277794+00');
