INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('08f73b98-a7c2-4fb4-be61-a6d0bdb07c2f', '3f9fa54c-35f3-4672-b833-5e9fd8f22427', 'Ser una donación anual sin diagnóstico.', false, 'Incorrecto. La ayuda aislada puede aliviar necesidades puntuales, pero no asegura diagnóstico, continuidad, participación ni cambios sostenibles para la paz En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Ser una donación anual sin diagnóstico».', 1, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2a606746-338e-42b6-949c-0f006046a113', '3f9fa54c-35f3-4672-b833-5e9fd8f22427', 'Ser igual en todos los territorios.', false, 'Incorrecto. La paz territorial requiere adaptar las acciones a la historia, actores, capacidades y conflictos de cada contexto En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Ser igual en todos los territorios».', 2, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('23a2eae9-aabd-4152-bcd9-edf45018cdef', '3f9fa54c-35f3-4672-b833-5e9fd8f22427', 'Depender solo del área de comunicaciones.', false, 'Incorrecto. La opción ''Depender solo del área de comunicaciones'' limita el análisis esperado, porque no integra participación, contexto territorial, evidencia y sostenibilidad social.', 3, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('82b1d20d-f9cb-4b1d-a0cf-2b6b27706c1e', 'af9fb336-5634-427b-bc7d-f122a4d8edce', 'Porque cada territorio tiene historia, actores, capacidades y conflictos propios.', true, 'Correcto. Porque responde al criterio central del tema.', 0, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a8005a27-529d-4d4b-b4ba-7406cf91c884', 'af9fb336-5634-427b-bc7d-f122a4d8edce', 'Porque permite copiar modelos sin ajuste.', false, 'Incorrecto. La paz territorial requiere adaptar las acciones a la historia, actores, capacidades y conflictos de cada contexto En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Porque permite copiar modelos sin ajuste».', 1, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f3ddcd96-cd36-4c91-8637-3895e117fbfa', 'af9fb336-5634-427b-bc7d-f122a4d8edce', 'Porque elimina la necesidad de indicadores.', false, 'Incorrecto. La evaluación y los indicadores son necesarios para verificar avances, aprender de errores y ajustar las acciones de paz En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Porque elimina la necesidad de indicadores».', 2, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e6ba6ae3-fb0a-4f36-9778-fcf8ec97eac2', 'af9fb336-5634-427b-bc7d-f122a4d8edce', 'Porque privilegia decisiones externas rápidas.', false, 'Incorrecto. Diseñar o decidir sin consulta reduce la legitimidad y puede reproducir exclusiones o tensiones territoriales En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Porque privilegia decisiones externas rápidas».', 3, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c9fb89a2-7f49-4d2e-995b-02b86f4b9771', '4e8b634c-27cd-4ce7-a545-bdec9be96acf', 'Que una empresa asume todas las funciones públicas.', false, 'Incorrecto. La responsabilidad social puede complementar la acción pública, pero no reemplaza las obligaciones del Estado ni las políticas institucionales En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Que una empresa asume todas las funciones públicas».', 0, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('86744044-be4c-449d-bf7c-6c03231e2d09', '4e8b634c-27cd-4ce7-a545-bdec9be96acf', 'Que comunidad, Estado, empresa, academia y organizaciones aportan desde responsabilidades diferenciadas.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2139f3b6-6b60-4dc2-8351-7e0b2336a972', '4e8b634c-27cd-4ce7-a545-bdec9be96acf', 'Que la comunidad debe resolver sola sus conflictos.', false, 'Incorrecto. La construcción de paz exige corresponsabilidad entre comunidad, Estado, empresas, academia y organizaciones sociales, no la carga exclusiva de un solo actor En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Que la comunidad debe resolver sola sus conflictos».', 2, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8311f8ee-2818-40f5-ba0e-7eb3c175310d', '4e8b634c-27cd-4ce7-a545-bdec9be96acf', 'Que los aliados no necesitan roles claros.', false, 'Incorrecto. Las alianzas útiles requieren coordinación, roles, compromisos y seguimiento; reunir actores sin acuerdos no fortalece la gobernanza En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Que los aliados no necesitan roles claros».', 3, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c29d89ab-65c3-4ffb-9e22-d8fccb147be4', 'edff3126-d63a-444d-a995-df600a465502', 'Fortalecimiento automático de asociaciones.', false, 'Incorrecto. Las asociaciones no se fortalecen automáticamente; requieren asistencia técnica, gobernanza, mercado y acompañamiento gradual.', 0, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c4c563d8-1a93-46ec-8fc4-c974048b399c', 'edff3126-d63a-444d-a995-df600a465502', 'Dependencia, incumplimientos y relaciones comerciales inequitativas.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
