INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8322f877-8ac7-48fd-abc2-80bf0b3e31ec', 'edff3126-d63a-444d-a995-df600a465502', 'Ausencia de necesidad de calidad.', false, 'Incorrecto. La inclusión económica debe acompañar capacidades, pero no elimina la necesidad de calidad y acuerdos comerciales viables.', 3, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
