INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e13755cf-06d3-421c-a1a5-6168acb6d849', 'b833663a-f3d4-4381-a1a2-149956c7472f', 'Porque reemplaza la participación comunitaria.', false, 'Incorrecto. Ninguna herramienta o principio reemplaza el diálogo comunitario, porque la legitimidad se construye con participación real En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Porque reemplaza la participación comunitaria».', 1, '2026-07-29 20:38:57.546111+00', '2026-07-29 20:38:57.546111+00');
