INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5a710b99-5889-4943-94f2-f7058e2c546b', '92c11e15-911e-4596-95bb-95800ffd9128', 'Sostenibilidad garantizada por la infraestructura.', false, 'Incorrecto. La infraestructura puede apoyar procesos sociales, pero sin gobernanza, participación y mantenimiento no garantiza construcción de paz En esta pregunta, ese matiz corresponde a un distractor diferente.', 3, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c7bab033-9397-4ff4-ac6f-38358ac587a8', 'b38d669d-db75-42fb-933e-36e687f94fee', 'La estrategia articula diagnóstico, participación, alianzas, evaluación y ajuste.', true, 'Correcto. Porque responde al criterio central del tema.', 0, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f733bee8-63c3-4c89-aef6-b7fad4c6c62c', 'b38d669d-db75-42fb-933e-36e687f94fee', 'La acción aislada siempre tiene mayor impacto.', false, 'Incorrecto. Una acción aislada suele carecer de articulación y seguimiento; el enfoque territorial requiere estrategia integrada.', 1, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('487ddb8b-0025-449f-a254-73dff757f13e', 'b38d669d-db75-42fb-933e-36e687f94fee', 'La estrategia evita indicadores.', false, 'Incorrecto. La evaluación y los indicadores son necesarios para verificar avances, aprender de errores y ajustar las acciones de paz En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «La estrategia evita indicadores».', 2, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('14b43c7d-0c4d-4391-95b6-f8b5d6391fe0', 'b38d669d-db75-42fb-933e-36e687f94fee', 'La acción aislada incorpora mejor el enfoque territorial.', false, 'Incorrecto. Una acción aislada suele carecer de articulación y seguimiento; el enfoque territorial requiere estrategia integrada En esta pregunta, ese matiz corresponde a un distractor diferente.', 3, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('36a77e80-cfff-402d-9282-a29f11c25728', '3ccdbc41-3502-49ce-b974-8b3a99ce4b20', 'Alinea capacidades organizacionales con necesidades sociales legítimas y sostenibles.', true, 'Correcto. Porque responde al criterio central del tema.', 0, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dad40303-7d02-484c-8931-3d5841e67d8f', '3ccdbc41-3502-49ce-b974-8b3a99ce4b20', 'Permite presentar cualquier beneficio empresarial como paz.', false, 'Incorrecto. No todo beneficio empresarial aporta a la paz; debe existir relación legítima con necesidades sociales y transformación territorial.', 1, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('22c6f95a-56de-4e0c-9f4d-4a1d0fd93c71', '3ccdbc41-3502-49ce-b974-8b3a99ce4b20', 'Ignora impactos comunitarios.', false, 'Incorrecto. La integración exige revisar cómo las decisiones organizacionales afectan el territorio; separar operación e impactos debilita la coherencia ética En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Ignora impactos comunitarios».', 2, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8a9a90a1-aeb6-4485-b3f1-d08fd2c72e47', '3ccdbc41-3502-49ce-b974-8b3a99ce4b20', 'Reemplaza la rendición de cuentas.', false, 'Incorrecto. La opción ''Reemplaza la rendición de cuentas'' limita el análisis esperado, porque no integra participación, contexto territorial, evidencia y sostenibilidad social.', 3, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('eb484eba-7c82-4222-9f8f-da4d9ca0f59b', '268f8d60-c684-4509-b449-476e8ff31303', 'Solo cobertura y número de actividades.', false, 'Incorrecto. Contar actividades o cobertura informa ejecución, pero no prueba cambios en convivencia, confianza, inclusión o capacidades En esta pregunta, ese matiz corresponde a un distractor diferente.', 0, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7a9cae53-2895-4ac9-a1d5-25261b2cff1c', '268f8d60-c684-4509-b449-476e8ff31303', 'Cambios en relaciones comunitarias, inclusión, confianza, participación y sostenibilidad.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5e321f51-afcd-4529-a5cf-f8fcaca8635b', '268f8d60-c684-4509-b449-476e8ff31303', 'Solo el cumplimiento del cronograma.', false, 'Incorrecto. Los recursos, costos o tiempos administrativos no bastan para valorar la paz; deben analizarse pertinencia, participación, confianza e impacto En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Solo el cumplimiento del cronograma».', 2, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('07f0f1d2-29cb-44e6-920a-55c15a6cca11', '268f8d60-c684-4509-b449-476e8ff31303', 'Únicamente la opinión de la organización ejecutora.', false, 'Incorrecto. Una comunicación centrada solo en la organización excluye la voz comunitaria y reduce la rendición de cuentas a un mensaje unilateral En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Únicamente la opinión de la organización ejecutora».', 3, '2026-07-29 20:39:38.510315+00', '2026-07-29 20:39:38.510315+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('69870247-903e-4212-b366-2dd1a1ecd3c3', 'e94a5e94-c528-4534-b466-02ec72976954', 'La entrega ocasional de ayudas sin seguimiento.', false, 'Incorrecto. La ayuda aislada puede aliviar necesidades puntuales, pero no asegura diagnóstico, continuidad, participación ni cambios sostenibles para la paz En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «La entrega ocasional de ayudas sin seguimiento».', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('83b4dfae-50b6-4694-a095-e75c6f1c5e90', 'e94a5e94-c528-4534-b466-02ec72976954', 'La generación de cambios sociales sostenibles mediante reconocimiento de impactos y diálogo con grupos de interés.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('eda0f5a0-4067-4205-aef8-c4b4a372e0d3', 'e94a5e94-c528-4534-b466-02ec72976954', 'La comunicación de logros sin evidencia.', false, 'Incorrecto. La comunicación o visibilidad no demuestra impacto social; se requieren evidencias, participación comunitaria y resultados verificables En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «La comunicación de logros sin evidencia».', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e30cf03b-86e6-4f0f-9860-32fde81edbcf', 'e94a5e94-c528-4534-b466-02ec72976954', 'La aplicación de la misma intervención en todos los lugares.', false, 'Incorrecto. La paz territorial requiere adaptar las acciones a la historia, actores, capacidades y conflictos de cada contexto En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «La aplicación de la misma intervención en todos los lugares».', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
