INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c99f6aaa-de72-493b-a937-97f1d49a2b83', '909d523b-3ad6-40bd-b153-4c453d5b7d04', 'Porque no todas las personas enfrentan las mismas barreras, riesgos y oportunidades.', true, 'Correcto. Porque responde al criterio central del tema.', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6c3707e0-dc8b-47a1-9936-a41eb28ba8d5', '909d523b-3ad6-40bd-b153-4c453d5b7d04', 'Porque permite excluir grupos complejos.', false, 'Incorrecto. El enfoque diferencial busca incluir a quienes enfrentan mayores barreras, no apartarlos por la complejidad de su situación.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fce8e1b1-fe13-4e3f-8ce3-37395f1376e8', '909d523b-3ad6-40bd-b153-4c453d5b7d04', 'Porque solo es una mención formal.', false, 'Incorrecto. El enfoque diferencial debe traducirse en cambios de diseño, accesibilidad, criterios y acompañamiento, no solo en una frase.', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('52909fd5-462b-4bc0-89cd-6b2f37335603', '909d523b-3ad6-40bd-b153-4c453d5b7d04', 'Porque reemplaza la evaluación de resultados.', false, 'Incorrecto. La evaluación y los indicadores son necesarios para verificar avances, aprender de errores y ajustar las acciones de paz En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Porque reemplaza la evaluación de resultados».', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3e1ae773-3c38-4c60-9728-7a4a4d2356e3', 'cc563904-aaea-48de-a29b-a8879696db65', 'Fortalece automáticamente la confianza.', false, 'Incorrecto. La confianza, la sostenibilidad y el impacto no se producen automáticamente; dependen de procesos verificables y sostenidos En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Fortalece automáticamente la confianza».', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d73f094d-6497-41dd-94db-e14b854503d7', 'cc563904-aaea-48de-a29b-a8879696db65', 'Puede convertir la responsabilidad social en espectáculo y generar rechazo.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('75249657-61df-4190-8d90-f95094d6d0ba', 'cc563904-aaea-48de-a29b-a8879696db65', 'Aumenta la participación vinculante.', false, 'Incorrecto. La participación vinculante no aumenta por comunicar logros; requiere incidencia real y canales de respuesta.', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9947b3a4-7311-4200-91a0-1182fb6e0620', 'cc563904-aaea-48de-a29b-a8879696db65', 'Garantiza sostenibilidad social.', false, 'Incorrecto. La confianza, la sostenibilidad y el impacto no se producen automáticamente; dependen de procesos verificables y sostenidos En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Garantiza sostenibilidad social».', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('76731035-34c1-4022-b1cd-4620e56c408b', '8d3d85cc-1993-4d1f-9687-79d79f8f95f7', 'Resultado equivale a publicar informes.', false, 'Incorrecto. Un resultado evidencia cambios inmediatos en capacidades o condiciones, no solo la publicación de informes.', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('87b5af3f-1384-4379-a0d9-70bd7455fa8a', '6f56038a-e7eb-4c00-bbee-b977c8a72b47', 'Como acuerdo abstracto sin expresión local.', false, 'Incorrecto. La paz territorial requiere adaptar las acciones a la historia, actores, capacidades y conflictos de cada contexto En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Como acuerdo abstracto sin expresión local».', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('630a05d9-c21a-443d-958b-75a8eefe93ac', '6f56038a-e7eb-4c00-bbee-b977c8a72b47', 'Como proceso situado en barrios, veredas y municipios, verificable en derechos, confianza y convivencia.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ccc27d0f-411a-43b4-b681-531b0fbc605e', '6f56038a-e7eb-4c00-bbee-b977c8a72b47', 'Como ausencia total de conflictos.', false, 'Incorrecto. La paz no consiste en callar o eliminar diferencias, sino en tramitar los conflictos mediante diálogo, derechos y acuerdos legítimos En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Como ausencia total de conflictos».', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('10ab540f-c54c-464a-bac0-20c931c5fa76', '6f56038a-e7eb-4c00-bbee-b977c8a72b47', 'Como responsabilidad exclusiva de la comunidad.', false, 'Incorrecto. La construcción de paz exige corresponsabilidad entre comunidad, Estado, empresas, academia y organizaciones sociales, no la carga exclusiva de un solo actor En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Como responsabilidad exclusiva de la comunidad».', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0377f8ce-2648-470d-ba17-ff3af3fc3042', '4456ee12-430f-4622-b3d1-692d391bf576', 'Convierte necesidades y conflictos en proyectos pertinentes, éticos y evaluables.', true, 'Correcto. Porque responde al criterio central del tema.', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('77563617-1c33-4f5a-85ae-97a470525ef0', '4456ee12-430f-4622-b3d1-692d391bf576', 'Elimina la complejidad humana mediante formatos.', false, 'Incorrecto. Los formatos ayudan a organizar, pero no eliminan memorias, relaciones de poder ni complejidades humanas del territorio.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('990f0d25-7511-486c-ad10-ca34be5b3bc0', '4456ee12-430f-4622-b3d1-692d391bf576', 'Sustituye la justicia y las políticas públicas.', false, 'Incorrecto. La responsabilidad social puede complementar la acción pública, pero no reemplaza las obligaciones del Estado ni las políticas institucionales En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Sustituye la justicia y las políticas públicas».', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('36c329db-a9e2-4d2b-b385-ee4dd31291e2', '4456ee12-430f-4622-b3d1-692d391bf576', 'Reduce la paz a actividades simbólicas.', false, 'Incorrecto. Los actos simbólicos pueden ser valiosos, pero no sustituyen procesos continuos de participación, reparación, capacidades y seguimiento En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Reduce la paz a actividades simbólicas».', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('311be5d4-df16-4977-a93a-7f33d5476687', '037833d8-8f7b-42f6-8de0-61fbd6713e8d', 'Ocultar desacuerdos para evitar incomodidad.', false, 'Incorrecto. La paz no consiste en callar o eliminar diferencias, sino en tramitar los conflictos mediante diálogo, derechos y acuerdos legítimos En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Ocultar desacuerdos para evitar incomodidad».', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('76d9157b-a2d3-444f-9acb-b4d6cdfbf703', '037833d8-8f7b-42f6-8de0-61fbd6713e8d', 'Modificar causas, relaciones y estructuras que sostienen confrontaciones.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('25f1a8f4-02f5-46b4-b68e-3767208026fc', '037833d8-8f7b-42f6-8de0-61fbd6713e8d', 'Imponer soluciones externas rápidas.', false, 'Incorrecto. Diseñar o decidir sin consulta reduce la legitimidad y puede reproducir exclusiones o tensiones territoriales En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Imponer soluciones externas rápidas».', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('de59deea-ac54-4cbf-9c84-1421b2fbd4fa', '037833d8-8f7b-42f6-8de0-61fbd6713e8d', 'Medir solo el número de reuniones.', false, 'Incorrecto. Contar reuniones no muestra transformación de conflictos; se necesitan cambios en acuerdos, relaciones y causas.', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('306c3ed7-62b5-478f-b5b4-bf031ca13abe', 'ce78cff3-a8ff-4452-a1a6-cfb5064afe01', 'Reuniones sin decisiones.', false, 'Incorrecto. Las alianzas útiles requieren coordinación, roles, compromisos y seguimiento; reunir actores sin acuerdos no fortalece la gobernanza En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Reuniones sin decisiones».', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dd351648-8bb6-4209-b3c6-f38997abad8d', 'ce78cff3-a8ff-4452-a1a6-cfb5064afe01', 'Roles claros, transparencia, corresponsabilidad, recursos y evaluación.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2fbfc32c-db84-493b-a7cc-84909b6021d8', 'ce78cff3-a8ff-4452-a1a6-cfb5064afe01', 'Dominio de un actor sobre los demás.', false, 'Incorrecto. La gobernanza colaborativa exige equilibrio y corresponsabilidad, no control unilateral de un actor.', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f635cb9f-01b0-4f64-b34d-626df2d051ed', 'ce78cff3-a8ff-4452-a1a6-cfb5064afe01', 'Ausencia de reglas de coordinación.', false, 'Incorrecto. Sin reglas de coordinación se debilitan los roles, la transparencia y la evaluación compartida.', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('096ea284-c230-4186-bad2-949f8ee69ccc', 'ed929879-106a-4113-ab09-0261d33b410f', 'Porque toda intervención en contextos de conflicto puede generar efectos no deseados.', true, 'Correcto. Porque responde al criterio central del tema.', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c0a51fa1-a621-41c1-8bec-24b5f3a28c43', 'ed929879-106a-4113-ab09-0261d33b410f', 'Porque permite evitar diagnósticos.', false, 'Incorrecto. El diagnóstico territorial es indispensable para comprender actores, riesgos y necesidades antes de intervenir o recomendar En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Porque permite evitar diagnósticos».', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('70954df8-0412-4ab2-a7a4-e1356c7180b3', 'ed929879-106a-4113-ab09-0261d33b410f', 'Porque reemplaza la participación comunitaria.', false, 'Incorrecto. Ninguna herramienta o principio reemplaza el diálogo comunitario, porque la legitimidad se construye con participación real En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Porque reemplaza la participación comunitaria» dentro de la prevención de daños.', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c1e9a375-bee8-4ea2-ad48-65d0e4cf759f', 'ed929879-106a-4113-ab09-0261d33b410f', 'Porque impide evaluar resultados.', false, 'Incorrecto. La evaluación y los indicadores son necesarios para verificar avances, aprender de errores y ajustar las acciones de paz En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Porque impide evaluar resultados».', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('de045690-04db-4b60-a9b3-77a96dba96c1', '8d3d85cc-1993-4d1f-9687-79d79f8f95f7', 'Todos miden solo asistencia.', false, 'Incorrecto. La participación no se limita a asistir o firmar; debe permitir deliberar, incidir y hacer seguimiento a las decisiones En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Todos miden solo asistencia».', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('077c7f37-783e-4d7b-bcb7-31f007543570', '8d3d85cc-1993-4d1f-9687-79d79f8f95f7', 'Proceso observa actividades; resultado cambios inmediatos; impacto transformaciones más profundas.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('073d4235-dad9-42d7-8600-83836729808c', '8d3d85cc-1993-4d1f-9687-79d79f8f95f7', 'Impacto se refiere únicamente al presupuesto.', false, 'Incorrecto. Los recursos, costos o tiempos administrativos no bastan para valorar la paz; deben analizarse pertinencia, participación, confianza e impacto En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Impacto se refiere únicamente al presupuesto».', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c6cfd31b-bd50-4ea1-8f6c-29e00bc7975a', 'df650722-5d2e-4940-9cd9-5772f1a8e47b', 'Publicar un afiche anual sin rutas de atención.', false, 'Incorrecto. El afiche aislado tiene bajo impacto transformador.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e4c06bbf-c401-4a11-ba84-ec0b7d07a1ab', '6c47abd1-e86c-438d-8372-e58f8300251b', 'Aplicar recetas universales sin adaptación.', false, 'Incorrecto. La paz territorial requiere adaptar las acciones a la historia, actores, capacidades y conflictos de cada contexto En esta pregunta, ese matiz corresponde a un distractor diferente En esta opción, el distractor específico es «Aplicar recetas universales sin adaptación».', 0, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f9ef24a8-1323-4c57-8697-52034c583152', '6c47abd1-e86c-438d-8372-e58f8300251b', 'Leer contextos, facilitar diálogo, formular proyectos, evaluar y comunicar con responsabilidad.', true, 'Correcto. Porque responde al criterio central del tema.', 1, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7f852c2a-7b4e-4b69-a5ed-2720f27b3b29', '6c47abd1-e86c-438d-8372-e58f8300251b', 'Evitar el trabajo colaborativo.', false, 'Incorrecto. Evitar el trabajo colaborativo reduce la articulación de actores necesaria para gestionar paz territorial.', 2, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1d9456cd-7966-4b01-b55d-bccbcb4e43cd', '6c47abd1-e86c-438d-8372-e58f8300251b', 'Separar ética y técnica en la intervención.', false, 'Incorrecto. En gerencia social, la técnica debe estar unida a criterios éticos para prevenir daños y orientar decisiones responsables.', 3, '2026-07-29 20:40:07.509924+00', '2026-07-29 20:40:07.509924+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f4912676-96cb-4dc5-bc40-0d0c6b9cded7', 'bc1f02e2-defb-46c0-bb81-87acbbcf9911', 'La eliminación de toda desigualdad estructural.', false, 'Incorrecto. Esa descripción corresponde más a aspiraciones de paz positiva y justicia social.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4a89a295-499c-4e9c-b239-c6d07d47ba73', 'bc1f02e2-defb-46c0-bb81-87acbbcf9911', 'La ausencia o disminución significativa de violencia directa.', true, 'Correcto. La paz negativa se concentra en reducir agresiones visibles y amenazas inmediatas.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ae1a0ea6-a37e-4ade-bfa9-f7cb6846e7fe', 'bc1f02e2-defb-46c0-bb81-87acbbcf9911', 'La obligación de olvidar daños para convivir.', false, 'Incorrecto. La reconciliación no exige olvido ni sustituye verdad y reparación.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c7d4ca6f-3d00-4143-abfb-da4f64260c49', 'bc1f02e2-defb-46c0-bb81-87acbbcf9911', 'La participación comunitaria con incidencia plena.', false, 'Incorrecto. La participación es otro componente, pero no define por sí sola la paz negativa.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6715b00e-6cce-4571-b923-7525163f633c', '8e302567-d1ef-423f-836e-e014954554ce', 'Menos enfrentamientos, pero líderes sociales sin garantías para reunirse.', false, 'Incorrecto. La reducción de enfrentamientos no basta si persisten miedo y restricciones.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('cfc38f25-4b0e-4727-a7a9-569166f3cad4', '8e302567-d1ef-423f-836e-e014954554ce', 'Acceso a derechos, participación y confianza institucional en un territorio.', true, 'Correcto. La paz positiva se observa en condiciones de dignidad, justicia y bienestar.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7ece5ac0-033d-4a35-bcbc-30f583db66aa', '8e302567-d1ef-423f-836e-e014954554ce', 'Una campaña de convivencia sin seguimiento ni recursos.', false, 'Incorrecto. La sensibilización aislada no demuestra transformación estructural.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4cafeebf-721c-4f1e-ac05-1172b6dec613', '8e302567-d1ef-423f-836e-e014954554ce', 'Control policial sin mecanismos de rendición de cuentas.', false, 'Incorrecto. La seguridad sin derechos puede debilitar legitimidad democrática.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c450b97c-698c-4383-a40c-a9848bf0ad8a', '702c1ed2-51e4-4794-ae55-65832d0ec430', 'Porque convierten la paz en una obligación de dignidad, garantías y límites al poder.', true, 'Correcto. Los derechos orientan políticas y evitan que la paz se confunda con obediencia.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d40ce17e-8426-4ae5-9b4c-31a0a895da88', '702c1ed2-51e4-4794-ae55-65832d0ec430', 'Porque reemplazan cualquier forma de participación comunitaria.', false, 'Incorrecto. Los derechos requieren participación para ser efectivos y contextualizados.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7275a8bc-6049-4458-be51-586fdbde283b', '702c1ed2-51e4-4794-ae55-65832d0ec430', 'Porque solo aplican después de que termina todo conflicto.', false, 'Incorrecto. Los derechos deben protegerse antes, durante y después de los conflictos.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a7b9c593-92e7-48be-964f-c1e510b2a0cb', '702c1ed2-51e4-4794-ae55-65832d0ec430', 'Porque permiten sacrificar libertades en nombre de la tranquilidad.', false, 'Incorrecto. Los derechos son límites frente a abusos, incluso cuando se invoca la seguridad.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('98887658-d621-4ae2-9b5e-5f68454db09b', '8b9a7ef3-b0db-4a79-b792-13d14638a81e', 'Reconocer daños y responsabilidades antes del encuentro.', false, 'Incorrecto. Esa es una condición responsable para reconstruir confianza.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('13199196-b7da-4eba-b6f9-215f32f320cc', '8b9a7ef3-b0db-4a79-b792-13d14638a81e', 'Crear espacios seguros de diálogo y memoria.', false, 'Incorrecto. Los espacios seguros favorecen reconocimiento y convivencia no violenta.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9ccfb630-de07-4f9b-8851-4975fc9be821', '8b9a7ef3-b0db-4a79-b792-13d14638a81e', 'Exigir perdón rápido sin verdad, reparación ni garantías.', true, 'Correcto. Esa práctica puede revictimizar y convertir la reconciliación en imposición.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d7d9ea4b-8096-4663-810e-c7982987e764', '8b9a7ef3-b0db-4a79-b792-13d14638a81e', 'Relacionar reconciliación con derechos y dignidad de las víctimas.', false, 'Incorrecto. La reconciliación sostenible necesita derechos, memoria y no repetición.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fa9172aa-a345-4612-ad44-f5758d8f67b1', '2c792496-ffce-4d4f-ad7e-1e3708e49040', '¿Qué actividad se puede realizar más rápido para mostrar resultados?', false, 'Incorrecto. La rapidez no reemplaza la comprensión de daños, actores y condiciones.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2968b19c-3b0e-4e0c-a4be-3dd6a57b2077', '2c792496-ffce-4d4f-ad7e-1e3708e49040', '¿Qué amenazas, derechos, desigualdades y relaciones requieren atención articulada?', true, 'Correcto. Esta pregunta reconoce la paz como sistema de componentes interdependientes.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0d887ed9-92a2-454e-88eb-a4895fcea85a', '2c792496-ffce-4d4f-ad7e-1e3708e49040', '¿Cómo evitar que la comunidad participe en decisiones técnicas?', false, 'Incorrecto. Excluir actores afectados reduce pertinencia y legitimidad.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3d5e0035-876d-4b4a-9dff-9aa702c79897', '2c792496-ffce-4d4f-ad7e-1e3708e49040', '¿Qué indicador administrativo permite cerrar el proceso?', false, 'Incorrecto. Un indicador aislado no prueba cambios en convivencia, derechos o confianza.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('cbd087f7-c896-4aca-9a7d-ae4db4574da1', '45f5581a-798e-40a2-ab21-214d87d8a226', 'La distribución digna de oportunidades y el reconocimiento de grupos excluidos.', true, 'Correcto. La justicia social reduce condiciones que alimentan violencia y desconfianza.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1d1afefa-7a13-46ac-91cd-8ec2537d0d6b', '45f5581a-798e-40a2-ab21-214d87d8a226', 'La imposición de silencio sobre conflictos legítimos.', false, 'Incorrecto. La paz democrática permite tramitar desacuerdos con garantías.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6dde306b-f57e-4f82-bc57-27ea853a13f1', '45f5581a-798e-40a2-ab21-214d87d8a226', 'La sustitución de derechos por asistencia ocasional.', false, 'Incorrecto. La asistencia aislada no equivale a acceso efectivo ni reconocimiento.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0279d178-5d08-4b1f-85b6-6f1547b03523', '45f5581a-798e-40a2-ab21-214d87d8a226', 'La vigilancia permanente de comunidades vulnerables.', false, 'Incorrecto. Esa medida puede aumentar estigmas si no se orienta desde derechos.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f46918d7-fe0f-482f-963d-75f0ce3b0ede', '4560557c-dec9-4b69-b76d-38543dfc1f58', 'Porque las relaciones, instituciones e imaginarios dañados no cambian con acciones aisladas.', true, 'Correcto. La paz exige procesos sostenidos de confianza, derechos, memoria y evaluación.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f2439661-2ea7-4c90-b101-5a456b47663d', '4560557c-dec9-4b69-b76d-38543dfc1f58', 'Porque la paz se logra únicamente con una campaña masiva.', false, 'Incorrecto. Las campañas pueden apoyar, pero no sustituyen transformaciones verificables.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('af047ad9-86b7-4cf6-9d33-4d6cbe1db1e2', '4560557c-dec9-4b69-b76d-38543dfc1f58', 'Porque debe suspender toda discusión pública.', false, 'Incorrecto. El desacuerdo democrático puede fortalecer la paz si se tramita sin violencia.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8d4f99e3-f3f1-4c7c-97ef-5316fcea1c0b', '4560557c-dec9-4b69-b76d-38543dfc1f58', 'Porque solo depende de una autoridad central.', false, 'Incorrecto. La paz necesita instituciones, comunidades y actores sociales articulados.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9b6dac4d-c848-4801-9d34-b5392a3a8c01', 'd605ce68-5f08-4112-bc67-5731018970be', 'Negar los conflictos para que no se hagan visibles.', false, 'Incorrecto. Prevenir no es ocultar desacuerdos, sino evitar que escalen a violencia.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e8a6023b-2f52-42d2-85b6-ee07a096f66e', '1d27f5c8-fec1-4be1-8f04-60945b98a644', 'Ocultando información para evitar críticas.', false, 'Incorrecto. La opacidad deteriora credibilidad y aumenta rumores.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0edeb58c-e7c4-4020-8139-5f753d57944b', 'd605ce68-5f08-4112-bc67-5731018970be', 'Anticipar factores de riesgo y crear condiciones para tramitar diferencias sin agresión.', true, 'Correcto. La prevención combina alertas, diálogo, protección y capacidades comunitarias.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8fc0d1c4-99c5-4865-a8ea-e9ccaeee9478', 'd605ce68-5f08-4112-bc67-5731018970be', 'Castigar toda expresión de inconformidad.', false, 'Incorrecto. La inconformidad puede ser legítima y debe contar con canales democráticos.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9ca3014f-0d34-4e9c-88d5-90aa737cc168', 'd605ce68-5f08-4112-bc67-5731018970be', 'Esperar a que ocurra el daño para intervenir.', false, 'Incorrecto. La prevención actúa antes del escalamiento y también aprende del daño previo.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f04e0d95-50cb-4685-91d9-5915b7da934e', 'b0e8fdc2-62a2-433e-aa2c-8088836ba0ab', 'Exigiendo confianza inmediata a las víctimas.', false, 'Incorrecto. La confianza no se impone; se recupera con cuidado, cumplimiento y reconocimiento.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('38d6b0bb-98fa-4093-9660-22e319f5e2eb', 'b0e8fdc2-62a2-433e-aa2c-8088836ba0ab', 'Mediante transparencia, cumplimiento de acuerdos, protección y rendición de cuentas.', true, 'Correcto. Estos elementos hacen creíble el proceso ante comunidades e instituciones.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ad0e2b4e-845e-41b9-a308-c26275b81c45', 'b0e8fdc2-62a2-433e-aa2c-8088836ba0ab', 'Eliminando las críticas al proceso institucional.', false, 'Incorrecto. La crítica responsable ayuda a corregir fallas y fortalecer legitimidad.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1f728a39-8205-4e9a-bf41-3262aa809e5e', 'b0e8fdc2-62a2-433e-aa2c-8088836ba0ab', 'Convocando reuniones sin compromisos verificables.', false, 'Incorrecto. La convocatoria vacía puede aumentar frustración y desconfianza.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f08fcee3-23f5-423d-a849-08b05c5b2119', 'bebd62a5-0689-46c7-bc1c-926e66c6e445', 'Se fortalece automáticamente la legitimidad institucional.', false, 'Incorrecto. El incumplimiento suele debilitar credibilidad y cooperación.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('bf24aebb-a596-425d-a4ea-3302fd015c6a', 'bebd62a5-0689-46c7-bc1c-926e66c6e445', 'Las víctimas dejan de necesitar reconocimiento.', false, 'Incorrecto. El incumplimiento puede profundizar el daño y la sensación de instrumentalización.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4031ea9e-adec-490b-8494-dfa53da9b83c', 'bebd62a5-0689-46c7-bc1c-926e66c6e445', 'Se rompe la confianza y la paz puede percibirse como discurso vacío.', true, 'Correcto. La coherencia institucional es condición básica de legitimidad.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ca1eac65-cecf-4f54-86b8-00bd7027a550', 'bebd62a5-0689-46c7-bc1c-926e66c6e445', 'La participación se vuelve innecesaria.', false, 'Incorrecto. Precisamente se requiere participación para rediseñar acuerdos y seguimiento.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e51e5e4c-2efb-45dc-8737-ff6501bde81a', '94c63a9a-7ffe-4e60-b501-13930cedc563', 'Invitar siempre a los mismos voceros sin verificar diversidad.', false, 'Incorrecto. Eso puede excluir voces y reproducir jerarquías locales.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('673d816a-7a16-4bda-bf02-e6c7b1c65f98', '94c63a9a-7ffe-4e60-b501-13930cedc563', 'Socializar decisiones ya tomadas para obtener asistencia.', false, 'Incorrecto. La socialización no garantiza incidencia ni deliberación.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6b27802b-33dd-4cc2-bc42-43cc5f9832ab', '94c63a9a-7ffe-4e60-b501-13930cedc563', 'Abrir espacios informados, seguros e incidentes para actores afectados.', true, 'Correcto. La participación real reconoce agencia, contexto y evaluación comunitaria.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0f30d0e0-92a5-4a6d-aa47-07b99fcb498d', '94c63a9a-7ffe-4e60-b501-13930cedc563', 'Evitar la participación para reducir conflictos.', false, 'Incorrecto. La exclusión puede aumentar desconfianza y debilitar sostenibilidad.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8e2c6454-449d-46ab-8071-16d66ac3b6a8', 'f39921cf-c5c6-44ab-af79-c07d3924520c', 'Porque las declaraciones generales no transforman condiciones que permitieron el daño.', true, 'Correcto. La no repetición exige responsables, recursos, reformas, pedagogía y seguimiento.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('82447fbe-d6cd-4c29-931d-761b9a2ab576', 'f39921cf-c5c6-44ab-af79-c07d3924520c', 'Porque basta con prometer que el daño no volverá a ocurrir.', false, 'Incorrecto. Las promesas sin acciones no protegen a comunidades ni previenen nuevas violencias.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('21c25756-6e6f-47f5-a669-9585ecba5179', 'f39921cf-c5c6-44ab-af79-c07d3924520c', 'Porque impide reconocer responsabilidades históricas.', false, 'Incorrecto. Reconocer responsabilidades ayuda a aprender y prevenir.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c19891f2-1ca3-48a4-a4aa-3ab550bb7477', 'f39921cf-c5c6-44ab-af79-c07d3924520c', 'Porque elimina la participación de comunidades afectadas.', false, 'Incorrecto. Las comunidades deben incidir en las medidas que buscan protegerlas.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8f00f0a5-5893-45a4-8916-e0b666d1914b', '7cc98d0f-7644-493d-95ab-e60a982d6ef1', 'Rapidez frente a profundidad en procesos de confianza y reparación.', true, 'Correcto. Los resultados inmediatos pueden ser insuficientes si no sostienen cambios reales.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('cf4432ae-fc73-4e40-ac9a-97ec89995644', '7cc98d0f-7644-493d-95ab-e60a982d6ef1', 'Ortografía frente a tamaño de archivo.', false, 'Incorrecto. Ese dilema técnico no corresponde al análisis sustantivo del proceso de paz.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1614a2b6-723f-406b-b56e-126504e84e38', '7cc98d0f-7644-493d-95ab-e60a982d6ef1', 'Diseño gráfico frente a color institucional.', false, 'Incorrecto. La forma puede ayudar, pero no define por sí sola la construcción de paz.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b0b56162-d950-4b99-8d82-fe12e1dbe0e8', '7cc98d0f-7644-493d-95ab-e60a982d6ef1', 'Cantidad de reuniones frente a decoración del aula.', false, 'Incorrecto. La cantidad de reuniones no prueba incidencia ni transformación.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('93c11269-bda9-452f-9306-c2388b19c532', '81d6cc3a-eca0-4fa5-8c99-e216c19f5506', 'La existencia de responsables, recursos, seguimiento, participación y evidencia de cambio.', true, 'Correcto. Un proceso sostenible articula acciones, evaluación y ajuste.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7403f900-deeb-42d0-9617-30208fc2c4a1', '81d6cc3a-eca0-4fa5-8c99-e216c19f5506', 'El número de afiches producidos durante la campaña.', false, 'Incorrecto. Los productos comunicativos no demuestran por sí solos transformación.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('da7417a2-806f-4319-bdc7-ac078f7cab4b', '81d6cc3a-eca0-4fa5-8c99-e216c19f5506', 'La ausencia de preguntas críticas de los participantes.', false, 'Incorrecto. Las preguntas críticas pueden mejorar el proceso y revelar riesgos.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0f8931da-4d3e-45a2-9f1c-c24cd1b1ab55', '81d6cc3a-eca0-4fa5-8c99-e216c19f5506', 'La rapidez con que se cierra el informe final.', false, 'Incorrecto. Cerrar rápido puede ocultar problemas no resueltos.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('896330b0-5636-47a7-abb3-8a19e34313fc', '6b589dcc-3594-4c12-b477-c354fc831ed9', 'Responder solo con vigilancia para mejorar la imagen de seguridad.', false, 'Incorrecto. La vigilancia aislada puede reforzar estigmas y alejar a los jóvenes.', 0, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('64c2130b-273a-42f3-a0bd-8f191084077a', '6b589dcc-3594-4c12-b477-c354fc831ed9', 'Combinar prevención, participación juvenil, oportunidades y garantías de seguridad.', true, 'Correcto. La respuesta integral reconoce riesgos reales sin criminalizar identidades.', 1, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2dcf246d-84f3-41f9-9f63-307d1700f1ee', '6b589dcc-3594-4c12-b477-c354fc831ed9', 'Cancelar espacios comunitarios para evitar discusión.', false, 'Incorrecto. Cerrar espacios limita deliberación y puede aumentar desconfianza.', 2, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('37a51b18-60e1-4713-b0bb-3253c4c844bb', '6b589dcc-3594-4c12-b477-c354fc831ed9', 'Centrarse en mensajes de reconciliación sin escuchar a los jóvenes.', false, 'Incorrecto. Sin escucha e incidencia, el mensaje puede parecer impuesto.', 3, '2026-07-30 16:42:00.503365+00', '2026-07-30 16:42:00.503365+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a9ca98c5-fbea-4446-8ac7-ee7dd95a20e0', '036c7558-176a-4e46-8018-41e590587497', 'La primera aborda el paso de la violencia a reglas no violentas; la segunda, la apertura de participación, derechos y controles al poder.', true, 'Correcto. Son procesos relacionados, pero cada uno enfatiza dimensiones distintas.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('698731bc-52ca-4d7b-bc19-873f1560935c', '036c7558-176a-4e46-8018-41e590587497', 'Ambas significan exactamente votar cada cuatro años.', false, 'Incorrecto. La democracia formal no agota la paz ni la democratización sustantiva.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('cdceee4e-8309-4c9d-8463-3035e3e3f96c', '036c7558-176a-4e46-8018-41e590587497', 'La transición democrática elimina automáticamente toda violencia territorial.', false, 'Incorrecto. Puede haber instituciones formales y persistencia de amenazas o exclusiones.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b891152d-5a87-4e3e-bd28-f1d24af77535', '036c7558-176a-4e46-8018-41e590587497', 'La transición hacia la paz no requiere instituciones ni participación.', false, 'Incorrecto. La paz sostenible necesita legitimidad, derechos y participación.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4bc04026-0dda-4117-959a-91fee793661b', '807fb607-491d-493a-bdc5-ef2620fa3dc6', 'Se reconoce de forma completa la experiencia territorial.', false, 'Incorrecto. Un acuerdo puede abrir oportunidades, pero no garantiza por sí mismo confianza ni derechos.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('034d12c1-9fae-44a6-b48b-23b218577c1b', '807fb607-491d-493a-bdc5-ef2620fa3dc6', 'Se invisibilizan implementación, reparación, seguridad humana y no repetición.', true, 'Correcto. La transición se prueba en cambios institucionales y comunitarios verificables.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('667c1227-8dce-49a5-9809-d79b770718ea', '807fb607-491d-493a-bdc5-ef2620fa3dc6', 'Se fortalece automáticamente la democracia sustantiva.', false, 'Incorrecto. La democracia sustantiva exige participación real y garantías de derechos.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4e3bfe52-d035-42fc-b485-b671e939b229', '807fb607-491d-493a-bdc5-ef2620fa3dc6', 'Se elimina toda necesidad de evaluación posterior.', false, 'Incorrecto. El seguimiento es indispensable para ajustar y prevenir retrocesos.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ac74ba74-df92-4e3c-bd65-c7358cf16ce1', '7869344e-4761-4cf9-851b-3d2f02554b8a', 'La existencia legal de una entidad, sin importar su práctica.', false, 'Incorrecto. La legalidad no basta si la población percibe arbitrariedad o incumplimiento.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3113d264-2bf4-4bcc-b78a-dfa66d367c49', '7869344e-4761-4cf9-851b-3d2f02554b8a', 'El reconocimiento social de que normas y autoridades actúan con justicia, respuesta y coherencia.', true, 'Correcto. La legitimidad se fortalece cuando las instituciones cumplen y protegen.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('514048cc-751f-414b-b788-2cd1b8ea6610', '7869344e-4761-4cf9-851b-3d2f02554b8a', 'La ausencia total de crítica ciudadana.', false, 'Incorrecto. La crítica puede ser parte de una democracia activa.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dbc7442f-31c6-44ae-a1f1-ca38d8d1b0d9', '7869344e-4761-4cf9-851b-3d2f02554b8a', 'La capacidad de imponer decisiones sin deliberación.', false, 'Incorrecto. La imposición puede debilitar confianza y participación.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('48fdb724-5a6e-4610-baac-09c5dbd045d3', '000c4870-fb38-4dbf-affd-f2b520980870', 'Elecciones formales sin garantías para liderazgos sociales.', false, 'Incorrecto. La democracia requiere seguridad para participar y oponerse.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5918d127-24af-4fbe-bdcc-55936612c41a', '000c4870-fb38-4dbf-affd-f2b520980870', 'Participación real, pluralismo, derechos, controles y capacidad de incidencia ciudadana.', true, 'Correcto. La democracia sustantiva va más allá del procedimiento electoral.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('efc504ca-e955-4ed2-ba53-1099b971fbf1', '000c4870-fb38-4dbf-affd-f2b520980870', 'Silenciamiento de demandas sociales para mantener estabilidad.', false, 'Incorrecto. La estabilidad sin derechos puede convertirse en pacificación.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a6dd9b26-4a81-44ae-8744-0f58ce8e4ba7', '000c4870-fb38-4dbf-affd-f2b520980870', 'Concentración de decisiones en actores técnicos externos.', false, 'Incorrecto. La deliberación y el control ciudadano son esenciales.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('51810731-7bed-4b0f-82d8-e82862137fdc', 'bbdce91d-3a08-41e0-a11a-6049ecbeaa14', 'Porque permite aplicar una receta única a todos los municipios.', false, 'Incorrecto. El enfoque territorial reconoce diferencias y evita soluciones uniformes.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0d11d94c-ba0f-4792-a077-a4494776149d', 'bbdce91d-3a08-41e0-a11a-6049ecbeaa14', 'Porque adapta acciones a historias, riesgos, actores y necesidades locales.', true, 'Correcto. La transición se experimenta de forma desigual en cada territorio.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6eee6f67-c444-4f8d-a758-a5d8b6238376', 'bbdce91d-3a08-41e0-a11a-6049ecbeaa14', 'Porque reemplaza los derechos humanos por costumbres locales.', false, 'Incorrecto. Las prácticas locales deben dialogar con un marco de derechos.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('75bb4444-7856-4630-8258-3207dfd9939e', 'bbdce91d-3a08-41e0-a11a-6049ecbeaa14', 'Porque evita escuchar a víctimas y comunidades.', false, 'Incorrecto. La escucha territorial fortalece legitimidad y pertinencia.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9320027b-dbf1-47d6-91b3-0f12b728ea92', '71b5d4de-3d4b-4718-b9b0-539ca16fb621', 'Actas de asistencia sin cambios en decisiones.', false, 'Incorrecto. La asistencia no demuestra incidencia.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('01526deb-a8be-48b0-bcc1-b34599d9c79e', '71b5d4de-3d4b-4718-b9b0-539ca16fb621', 'Compromisos públicos, diversidad de voces, seguimiento y respuesta institucional.', true, 'Correcto. La participación efectiva produce efectos verificables y confianza.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('49de56aa-40e6-4967-bb65-bf7ff8ec36f2', '71b5d4de-3d4b-4718-b9b0-539ca16fb621', 'Decisiones cerradas antes de la deliberación.', false, 'Incorrecto. Eso convierte la participación en trámite.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c5c58c13-6c18-4379-916b-05bc886acbbe', '71b5d4de-3d4b-4718-b9b0-539ca16fb621', 'Ausencia de información técnica para la comunidad.', false, 'Incorrecto. Sin información clara, no hay deliberación equilibrada.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f04ef6bf-7373-4c8b-962c-a7c1c2488dc5', '94fb2d7b-af68-44a3-a93d-2f40093957f6', 'Que disminuya una forma de violencia pero se reconfiguren economías ilegales o amenazas.', true, 'Correcto. La transición debe atender causas y condiciones que reproducen violencias.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('95e746c3-2219-41a1-9b35-13e38f7110aa', '94fb2d7b-af68-44a3-a93d-2f40093957f6', 'Que las comunidades participen con seguridad y seguimiento.', false, 'Incorrecto. Eso sería un indicador positivo, no un riesgo.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4e928a32-e86a-4beb-9b12-5a6b54733f71', '94fb2d7b-af68-44a3-a93d-2f40093957f6', 'Que las instituciones rindan cuentas de manera verificable.', false, 'Incorrecto. La rendición de cuentas fortalece legitimidad.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2b1d4a20-a09e-432e-a11f-186f134dc7cb', '94fb2d7b-af68-44a3-a93d-2f40093957f6', 'Que se reconozcan derechos de víctimas.', false, 'Incorrecto. El reconocimiento es clave para no repetición.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ab751354-ea35-4001-bae5-6f0b14427d72', '507b6323-9cdc-477a-8aa0-ad16e2fcc747', 'Define qué se entiende por violencia, actores, causas y condiciones de transformación.', true, 'Correcto. La teoría orienta diagnóstico, metodología e indicadores.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d2fca126-a26f-4f4e-a069-b240e6d1cc6f', '507b6323-9cdc-477a-8aa0-ad16e2fcc747', 'Impide adaptar la intervención al contexto.', false, 'Incorrecto. Las teorías deben contextualizarse y evaluarse.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c828b42f-1f28-4407-8c07-0edeb02bb0be', '507b6323-9cdc-477a-8aa0-ad16e2fcc747', 'Sustituye la necesidad de participación local.', false, 'Incorrecto. La teoría no reemplaza la agencia de actores afectados.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dbec3b89-84f0-40fb-aeed-a0a478967a86', '507b6323-9cdc-477a-8aa0-ad16e2fcc747', 'Sirve para usar nombres de autores sin tomar decisiones.', false, 'Incorrecto. La teoría debe conectarse con acciones concretas.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('172d228a-1cc1-4668-b5ea-e21c593023c2', '0eceb80a-7193-4734-81f9-7a832bbd920f', 'La teoría explica el problema; el enfoque orienta cómo intervenir.', true, 'Correcto. Esta distinción ayuda a pasar del análisis a la práctica.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('bdc6ad40-d32d-40e3-b251-c8447d263c19', '0eceb80a-7193-4734-81f9-7a832bbd920f', 'El enfoque solo sirve para citar autores en bibliografía.', false, 'Incorrecto. El enfoque define métodos, criterios y población.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('54695e91-7f61-43e2-a6bc-dd7f5c8d64d4', '0eceb80a-7193-4734-81f9-7a832bbd920f', 'La teoría reemplaza el diagnóstico territorial.', false, 'Incorrecto. La teoría debe mejorar el diagnóstico, no eliminarlo.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('32bb150d-402f-428c-92cf-f0894545f24c', '0eceb80a-7193-4734-81f9-7a832bbd920f', 'Ambos conceptos significan una actividad aislada.', false, 'Incorrecto. Ninguno se reduce a actividades sueltas.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1ce971d4-a641-49e5-b311-cb72135b4994', 'eed06541-f62b-4131-a51e-5f38bf8c1307', 'La discusión sobre dónde se decide la paz y cómo se articulan Estado, comunidad y normas externas.', true, 'Correcto. Estos enfoques analizan legitimidad, apropiación local e institucionalidad.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('51895180-451d-48a2-9d7f-ce443275583f', 'eed06541-f62b-4131-a51e-5f38bf8c1307', 'La idea de que toda paz debe excluir instituciones públicas.', false, 'Incorrecto. La paz territorial no elimina responsabilidades estatales.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9e0cc22d-d5ce-4d57-96e1-155e419ee044', 'eed06541-f62b-4131-a51e-5f38bf8c1307', 'La obligación de copiar modelos internacionales sin adaptación.', false, 'Incorrecto. La crítica a la paz liberal advierte precisamente ese riesgo.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6a31a442-9e6b-4da3-8159-68a5be352b04', 'eed06541-f62b-4131-a51e-5f38bf8c1307', 'La imposibilidad de combinar derechos y participación.', false, 'Incorrecto. La paz sostenible requiere ambos elementos.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6690380e-bbdf-42fa-a9f2-bcb753a88570', '8390cb57-777c-4e43-894e-4d230f29b5b5', 'Paz negativa es justicia social plena; paz positiva es solo silencio de armas.', false, 'Incorrecto. La relación está invertida y simplificada.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4a21d948-d5ec-4bb9-84f6-f59190f1950a', '8390cb57-777c-4e43-894e-4d230f29b5b5', 'Paz negativa reduce violencia directa; paz positiva incorpora justicia, derechos y bienestar.', true, 'Correcto. Esta distinción ayuda a evaluar la profundidad de una intervención.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('785c914e-91d7-43f9-bc5b-b96f969fa856', '8390cb57-777c-4e43-894e-4d230f29b5b5', 'Ambas rechazan cualquier forma de participación ciudadana.', false, 'Incorrecto. La participación puede fortalecer paz positiva.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e8c8034e-9dc6-483d-bf3b-2cdf1480d03a', '8390cb57-777c-4e43-894e-4d230f29b5b5', 'Ambas se limitan a procedimientos electorales.', false, 'Incorrecto. Los debates de paz superan el plano electoral.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('cdc2e944-d493-49aa-9c8c-3df7b5cc3417', 'ec19a534-fc20-4bd3-bd64-70b2e4253c56', 'Puede convertirse en suma de actividades sin conexión entre diagnóstico, acción y resultado.', true, 'Correcto. La teoría de cambio permite justificar cómo se espera producir transformación.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1c065911-e0ac-4ba0-8b93-b3caec18a048', 'ec19a534-fc20-4bd3-bd64-70b2e4253c56', 'Garantiza automáticamente legitimidad comunitaria.', false, 'Incorrecto. La legitimidad requiere coherencia, participación y resultados.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('03dde4b2-3ee0-4a35-98ef-4731f57961a6', 'ec19a534-fc20-4bd3-bd64-70b2e4253c56', 'Evita toda fragmentación institucional.', false, 'Incorrecto. Sin teoría de cambio, la fragmentación puede aumentar.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('965939a2-c2ce-44f5-87e1-d3ce7a27be63', 'ec19a534-fc20-4bd3-bd64-70b2e4253c56', 'Hace innecesaria la evaluación.', false, 'Incorrecto. La evaluación es clave para verificar efectos y ajustar.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5b925a67-b4b1-490c-b3df-6c9960d07fb4', '7d7bcb27-68eb-4647-b8cb-0bb1c66dcbb5', 'Porque pregunta quién define la paz, con qué autoridad y mediante qué participación.', true, 'Correcto. La legitimidad evita intervenciones impuestas o desconectadas del territorio.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5ebe4480-f2ae-4a7c-83f8-eccb4b2b2689', '7d7bcb27-68eb-4647-b8cb-0bb1c66dcbb5', 'Porque elimina el marco de derechos humanos.', false, 'Incorrecto. La legitimidad crítica debe dialogar con derechos, no sustituirlos.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2780583c-d5e0-431b-9837-40e3c78dc006', '7d7bcb27-68eb-4647-b8cb-0bb1c66dcbb5', 'Porque convierte toda intervención externa en correcta.', false, 'Incorrecto. El debate evalúa apropiación, poder e intereses.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('01776d1a-0655-4654-92d7-693e5209c2b0', '7d7bcb27-68eb-4647-b8cb-0bb1c66dcbb5', 'Porque mide solo documentos producidos.', false, 'Incorrecto. La legitimidad incluye reconocimiento, participación y resultados percibidos como dignos.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4611b1ec-ec3b-432b-a8cb-c6d089789f84', '95bd7fa7-ecca-4f12-a274-b9d8b4ee0fa9', 'Solo el número de reuniones realizadas.', false, 'Incorrecto. La cantidad de reuniones no demuestra transformación.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3d5d261c-3cf9-40bf-8ce8-c79ada2addc7', '95bd7fa7-ecca-4f12-a274-b9d8b4ee0fa9', 'Confianza, participación, acceso a derechos, reparación o percepción de seguridad.', true, 'Correcto. La paz positiva requiere indicadores cuantitativos y cualitativos.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('cbb0e495-700e-4ef9-bc6c-087cdcdef15f', '95bd7fa7-ecca-4f12-a274-b9d8b4ee0fa9', 'Exclusivamente la rapidez de ejecución presupuestal.', false, 'Incorrecto. La eficiencia financiera no basta para evaluar paz.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('743b3cdf-2b03-4845-b942-dea4754a72b1', '95bd7fa7-ecca-4f12-a274-b9d8b4ee0fa9', 'La ausencia de críticas en redes sociales.', false, 'Incorrecto. El debate público no debe confundirse con fracaso.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('48210dce-5ea9-49fa-9dea-6aaacb696d45', 'cb4bd821-5607-4935-b962-ff139558677c', 'Reconoce capacidades comunitarias, saberes territoriales y prácticas cotidianas de convivencia.', true, 'Correcto. El giro local evita tratar a las comunidades como receptoras pasivas.', 0, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e2349b1c-d0df-4edc-9010-7cee3d28faa0', 'cb4bd821-5607-4935-b962-ff139558677c', 'Sostiene que lo local siempre es justo y homogéneo.', false, 'Incorrecto. Lo local también puede contener exclusiones y tensiones internas.', 1, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('db351284-3c51-4ce5-aef7-4f8dec7b2c29', 'cb4bd821-5607-4935-b962-ff139558677c', 'Rechaza cualquier coordinación institucional.', false, 'Incorrecto. La articulación con instituciones puede ser necesaria para garantizar derechos.', 2, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('76e18abe-da87-46f4-b8dc-c43bb3f8829e', 'cb4bd821-5607-4935-b962-ff139558677c', 'Impide analizar relaciones de poder.', false, 'Incorrecto. El análisis local debe revisar poder, riesgos y legitimidad.', 3, '2026-07-30 16:42:38.836129+00', '2026-07-30 16:42:38.836129+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('24ca9f73-74c3-45c6-ac40-c31ef9a443cb', 'f7d6c14c-b665-4e33-a87f-54e0bf0826e9', 'La distinción entre paz negativa, paz positiva y violencia directa, estructural y cultural.', true, 'Correcto. Galtung amplía el diagnóstico de la violencia y de las condiciones de paz.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9b4bb8db-0978-43c7-a2ce-e7398c9cb78a', 'f7d6c14c-b665-4e33-a87f-54e0bf0826e9', 'La idea de que la reconciliación exige olvido obligatorio.', false, 'Incorrecto. La reconciliación sostenible no debe imponer olvido.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8bb8caa3-3e89-474c-9ae0-6fe6cd0b9939', 'f7d6c14c-b665-4e33-a87f-54e0bf0826e9', 'La reducción de la paz a eventos conmemorativos.', false, 'Incorrecto. La cultura de paz requiere prácticas e instituciones sostenidas.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5080a5fd-d848-4cc0-b0f4-49d06dd687c3', 'f7d6c14c-b665-4e33-a87f-54e0bf0826e9', 'La exclusión de comunidades en la definición de iniciativas.', false, 'Incorrecto. La paz participativa exige incidencia de actores afectados.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fd3c05d2-8efd-4c9f-b8bc-fd9681ca1251', '069d6bfa-8224-40f2-9089-13d46e610424', 'Una agresión física visible y directa contra una persona.', false, 'Incorrecto. Esa definición corresponde a violencia directa.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f89d48f0-0a1d-47cf-80cd-9e0b3931b0ac', '069d6bfa-8224-40f2-9089-13d46e610424', 'Un daño producido por arreglos sociales que impiden satisfacer necesidades o ejercer derechos.', true, 'Correcto. La violencia estructural opera mediante desigualdades y barreras institucionales.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('72e9aead-9eb0-4e76-8f8c-e446307f0da9', '069d6bfa-8224-40f2-9089-13d46e610424', 'Un desacuerdo expresado pacíficamente en una comunidad.', false, 'Incorrecto. El desacuerdo no es violencia si se tramita con garantías.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9c1ec6bd-baf7-417e-b342-ede13d0c78f0', '069d6bfa-8224-40f2-9089-13d46e610424', 'Una actividad pedagógica de cultura de paz.', false, 'Incorrecto. La pedagogía puede enfrentar violencias, no definirlas.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('494c600a-221c-4386-b5db-4925c790c724', '1710f065-5e51-4bec-ac79-a766f2081644', 'La comprensión del conflicto como relación que puede transformarse con diálogo, reconocimiento e imaginación moral.', true, 'Correcto. Lederach enfatiza procesos relacionales y reconciliación sostenible.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e5578e13-20fa-4dbe-a36f-0799c71a9402', '1710f065-5e51-4bec-ac79-a766f2081644', 'La afirmación de que basta firmar acuerdos para reparar vínculos.', false, 'Incorrecto. Los acuerdos pueden ser necesarios, pero no reconstruyen confianza automáticamente.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fb19cd6f-02aa-4d24-96bf-a89428a025e7', '1710f065-5e51-4bec-ac79-a766f2081644', 'La eliminación de toda memoria para evitar tensiones.', false, 'Incorrecto. La memoria puede ser condición de reconocimiento y no repetición.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2eab60e5-9124-4aa2-934e-b051bccee7eb', '1710f065-5e51-4bec-ac79-a766f2081644', 'La medición de paz solo por reducción de incidentes.', false, 'Incorrecto. La paz también debe observar relaciones, confianza y participación.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5a0b1093-5f5c-4bda-beb4-bffbe5c2f626', '3e10831e-99ce-4094-b848-a39a5cd7ae88', 'Porque permite imaginar relaciones nuevas sin negar el daño ni las tensiones existentes.', true, 'Correcto. La imaginación moral abre posibilidades éticas de transformación.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8a0c7a48-dc1d-44c7-b334-f5033dd72111', '3e10831e-99ce-4094-b848-a39a5cd7ae88', 'Porque obliga a olvidar responsabilidades históricas.', false, 'Incorrecto. La transformación no exige borrar el pasado.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('efd67c55-3e34-467d-a444-7b8615f2d8d2', '3e10831e-99ce-4094-b848-a39a5cd7ae88', 'Porque reemplaza toda metodología por intuición individual.', false, 'Incorrecto. La creatividad ética necesita diseño, cuidado y seguimiento.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c1971c52-446d-4baa-90b9-7fd8a9d6df1a', '3e10831e-99ce-4094-b848-a39a5cd7ae88', 'Porque evita que actores enfrentados se escuchen.', false, 'Incorrecto. El enfoque busca crear espacios seguros de reconocimiento.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('00342fd1-6f2f-4d7a-84d2-8f19f21eb721', '0a0270b7-865b-4c35-a963-8f736d99e531', 'Un conjunto de prácticas, valores y aprendizajes para gestionar conflictos sin violencia.', true, 'Correcto. La cultura de paz se construye en hábitos, instituciones y educación.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('01c5f616-f6a6-4ec5-a1d4-59d85edc2a32', '0a0270b7-865b-4c35-a963-8f736d99e531', 'Una celebración simbólica que reemplaza cambios institucionales.', false, 'Incorrecto. Los actos simbólicos son insuficientes si no transforman prácticas.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3a221e94-a1b0-4403-8335-a4ae744156f8', '0a0270b7-865b-4c35-a963-8f736d99e531', 'Un método para prohibir el debate crítico.', false, 'Incorrecto. Educar para la paz implica crítica, responsabilidad y diálogo.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9b637f5b-30c7-4d95-ad48-6b30b972c845', '0a0270b7-865b-4c35-a963-8f736d99e531', 'Una estrategia exclusiva de seguridad coercitiva.', false, 'Incorrecto. La cultura de paz trabaja educación, derechos y gestión de conflictos.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6dac3476-cdc6-44a7-83fe-76f368ddb984', '926fd16d-fefb-43cd-86f6-d9c7f001afde', 'Transformar protocolos punitivos en rutas restaurativas.', false, 'Incorrecto. Eso puede fortalecer aprendizaje y reparación.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5dd4ac13-89d9-4d15-99e1-c4fbf4cc92f0', '926fd16d-fefb-43cd-86f6-d9c7f001afde', 'Reducir la cultura de paz a charlas, afiches o semanas conmemorativas sin cambios sostenidos.', true, 'Correcto. La cultura de paz necesita prácticas medibles y continuidad institucional.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('735c73c3-aa51-486d-899c-be61ec870f59', '926fd16d-fefb-43cd-86f6-d9c7f001afde', 'Formar capacidades de mediación y deliberación.', false, 'Incorrecto. Estas capacidades sostienen convivencia democrática.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('37433066-64f9-429a-acd8-f651ad1594ce', '926fd16d-fefb-43cd-86f6-d9c7f001afde', 'Relacionar educación con derechos humanos.', false, 'Incorrecto. La educación en derechos es núcleo de la cultura de paz.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e8456258-ba09-4282-a085-bbae2f4efdce', '4079ac4c-83e8-43be-9c12-6516423d73d4', 'Que la paz se construye con comunidades afectadas y no solo para ellas.', true, 'Correcto. El enfoque destaca agencia territorial, participación e incidencia real.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('577ea3df-888a-4ec6-ae40-1711114f7e26', '4079ac4c-83e8-43be-9c12-6516423d73d4', 'Que las comunidades deben recibir programas sin participar en decisiones.', false, 'Incorrecto. Eso contradice la paz participativa.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dbeca242-efca-4495-abaf-01ea0807ccf1', '4079ac4c-83e8-43be-9c12-6516423d73d4', 'Que la negociación de élites basta para transformar condiciones territoriales.', false, 'Incorrecto. La negociación es importante, pero no agota la construcción de paz.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('abc81471-94d1-4676-b332-68f7533ac941', '4079ac4c-83e8-43be-9c12-6516423d73d4', 'Que la participación se reduce a consulta decorativa.', false, 'Incorrecto. La participación debe incidir en diagnóstico, diseño y evaluación.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ba854126-9623-44f9-95c8-527719851188', '7b9afa28-2e06-4b23-8dd7-37998f4ba766', 'Diversidad de voces, seguridad, información clara, incidencia y seguimiento.', true, 'Correcto. Estos criterios evitan participación superficial o capturada.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('99387c29-16a0-4075-916e-0c25cb723e4a', '7b9afa28-2e06-4b23-8dd7-37998f4ba766', 'Presencia física sin capacidad de decisión.', false, 'Incorrecto. La asistencia no equivale a participación incidente.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4ee1a374-ce91-49c1-8d9c-56dafb517386', '7b9afa28-2e06-4b23-8dd7-37998f4ba766', 'Consulta a un solo vocero por rapidez administrativa.', false, 'Incorrecto. Un solo vocero puede no representar la diversidad territorial.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ad766bcc-e1c1-47b1-b86a-2864fc1f1e5d', '7b9afa28-2e06-4b23-8dd7-37998f4ba766', 'Ausencia de protección para quienes opinan.', false, 'Incorrecto. Sin garantías, la participación puede exponer a riesgos.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2dc0343e-a39d-4bdd-b961-f251f53b660c', 'aac4bbba-48d2-480b-8a15-5b173c1d3722', 'Olvidar el daño para cerrar el caso con rapidez.', false, 'Incorrecto. La reconciliación no puede imponerse ni borrar la verdad.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4d4c5921-f1e9-481c-a4df-e5a7a4e5e091', 'aac4bbba-48d2-480b-8a15-5b173c1d3722', 'Reconstruir relaciones con verdad, reconocimiento, justicia posible, reparación y no repetición.', true, 'Correcto. La reconciliación sostenible cuida dignidad y condiciones de convivencia.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ebaf31af-830c-4fbd-a060-12026c5d739f', 'aac4bbba-48d2-480b-8a15-5b173c1d3722', 'Declarar armonía sin escuchar a víctimas.', false, 'Incorrecto. Silenciar víctimas debilita legitimidad y confianza.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('796a77c1-e80d-4882-b9b8-cc7c89ec66c7', 'aac4bbba-48d2-480b-8a15-5b173c1d3722', 'Sustituir responsabilidades institucionales por discursos emotivos.', false, 'Incorrecto. Los discursos no reemplazan reparación ni garantías.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('df39de71-7530-4cda-b6ea-17fc4d56029c', 'ae670819-a8ba-4ca0-acc6-b3f80cafafc7', 'Galtung diagnostica violencias, Lederach transforma relaciones, Fisas sostiene cultura de paz y Ramos Muslera enfatiza participación territorial.', true, 'Correcto. La matriz comparada permite diseñar intervenciones más completas.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b35d0568-18f3-4544-b7c2-ccdde513bffa', 'ae670819-a8ba-4ca0-acc6-b3f80cafafc7', 'Todos proponen exactamente el mismo método sin diferencias.', false, 'Incorrecto. Cada autor aporta un lente distinto y complementario.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('44010a8a-7e90-44f3-b6a8-afcd52f17be2', 'ae670819-a8ba-4ca0-acc6-b3f80cafafc7', 'Todos reducen la paz al control policial.', false, 'Incorrecto. Sus enfoques amplían la paz hacia justicia, cultura, relaciones y participación.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e083f1fe-1b6c-4066-8d84-7afe64ec2cde', 'ae670819-a8ba-4ca0-acc6-b3f80cafafc7', 'Todos excluyen la educación de la construcción de paz.', false, 'Incorrecto. La dimensión educativa es central, especialmente en Fisas y Lederach.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('183b2cc3-e5db-4a49-b7f0-0487e6a66c19', '5d36be13-68b6-416f-84d6-eb1419fd6fdf', '¿Qué explica mejor cada enfoque, qué deja por fuera y cómo se aplica al contexto?', true, 'Correcto. Esta pregunta evita citas decorativas y orienta decisiones coherentes.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8b86eb2b-32b1-4b4f-bcc7-e4b25b4474cd', '5d36be13-68b6-416f-84d6-eb1419fd6fdf', '¿Qué autor permite ignorar el diagnóstico territorial?', false, 'Incorrecto. Ningún enfoque responsable reemplaza el diagnóstico.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('18c3e425-3be3-48cb-9b3d-2bf13772ca22', '5d36be13-68b6-416f-84d6-eb1419fd6fdf', '¿Cómo citar más autores sin cambiar la intervención?', false, 'Incorrecto. La teoría debe incidir en metodología y evaluación.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1b4df557-56d3-46ea-a887-94d55531c652', '5d36be13-68b6-416f-84d6-eb1419fd6fdf', '¿Cómo evitar reconocer tensiones entre enfoques?', false, 'Incorrecto. Reconocer tensiones fortalece el análisis.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b0663c26-b8eb-49c7-a19b-583aa15deab6', 'a7e2fc8a-d4fa-4093-919e-362e548e1b9f', 'Declarar paz completa porque no hay ataques visibles.', false, 'Incorrecto. Eso confunde paz negativa con paz integral.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3ab1d0a3-e8b8-459f-8c44-1fbe6ed00f68', 'a7e2fc8a-d4fa-4093-919e-362e548e1b9f', 'Diagnosticar violencias estructurales y culturales además de la violencia directa.', true, 'Correcto. El enfoque permite identificar daños invisibles y condiciones de exclusión.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('af2fd872-e6e7-4667-bbe2-51d65b160b45', 'a7e2fc8a-d4fa-4093-919e-362e548e1b9f', 'Evitar analizar instituciones para no politizar el caso.', false, 'Incorrecto. Las estructuras institucionales pueden reproducir o transformar daño.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f0d31c4d-c660-44f1-83df-035492677b12', 'a7e2fc8a-d4fa-4093-919e-362e548e1b9f', 'Centrarse solo en una ceremonia de cierre.', false, 'Incorrecto. El símbolo no sustituye cambios verificables.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('975788f1-15a9-46c7-ae41-e83923384cd6', 'ae214015-9ce3-4417-a911-fac90219503b', 'Buscar acuerdos rápidos sin reconocer miedos ni memorias.', false, 'Incorrecto. La rapidez puede producir acuerdos frágiles.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('454b4e4e-dc69-4dc7-8366-75c24c410199', 'ae214015-9ce3-4417-a911-fac90219503b', 'Diseñar espacios seguros, actores puente, escucha y compromisos graduales.', true, 'Correcto. La transformación relacional requiere confianza, reconocimiento y proceso.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9e5fea9a-b4d6-4752-8469-2d6ba72981f6', 'ae214015-9ce3-4417-a911-fac90219503b', 'Evitar que las partes se encuentren para no incomodarlas.', false, 'Incorrecto. La paz puede necesitar encuentros cuidadosamente diseñados.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('28f72878-8da7-4799-8a24-670591846f9d', 'ae214015-9ce3-4417-a911-fac90219503b', 'Asumir que un protocolo formal basta para reconstruir relaciones.', false, 'Incorrecto. Los protocolos ayudan, pero no sustituyen confianza.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('95a6001f-b5a5-4abe-a36e-f863bbf152e2', 'df650722-5d2e-4940-9cd9-5772f1a8e47b', 'Cambiar prácticas de aula, crear mediación, formar docentes y evaluar clima institucional.', true, 'Correcto. La cultura de paz se expresa en prácticas sostenidas y evaluables.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b8e620f2-e791-41eb-a6c3-ca0d32d37fcc', 'df650722-5d2e-4940-9cd9-5772f1a8e47b', 'Evitar debates sobre memoria para no incomodar.', false, 'Incorrecto. El debate puede ser pedagógico si se cuida con reglas y derechos.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fb5a5612-678a-44a4-89db-f87cc8e916a4', 'df650722-5d2e-4940-9cd9-5772f1a8e47b', 'Sancionar todo desacuerdo político.', false, 'Incorrecto. El desacuerdo debe tramitarse sin violencia, no eliminarse.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('282b60b8-84e0-4cda-83cb-78a317cf8574', '5a4092de-99a6-45e0-88e4-f8d11c3d2a55', 'Cuidar dignidad, evitar revictimización, reconocer asimetrías y definir evidencias de mejora.', true, 'Correcto. Trabajar paz exige responsabilidad con personas, memorias y riesgos.', 0, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f019ef05-ef18-48b2-8863-0b6355d0ba60', '5a4092de-99a6-45e0-88e4-f8d11c3d2a55', 'Prometer transformaciones sin capacidad de sostenerlas.', false, 'Incorrecto. Las promesas vacías deterioran confianza.', 1, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d03cb6f6-50cf-4a8c-a51c-ae5588077deb', '5a4092de-99a6-45e0-88e4-f8d11c3d2a55', 'Usar testimonios sin consentimiento para sensibilizar.', false, 'Incorrecto. Eso puede instrumentalizar a las víctimas.', 2, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e2f6460b-9191-43e1-a943-fc067ac15a4e', '5a4092de-99a6-45e0-88e4-f8d11c3d2a55', 'Aplicar recetas universales sin analizar contexto.', false, 'Incorrecto. Los enfoques deben adaptarse con sensibilidad territorial.', 3, '2026-07-30 16:42:57.709442+00', '2026-07-30 16:42:57.709442+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fa557199-b441-41d0-bb88-dc4229da087a', 'a3044ab9-5484-48ed-a246-9a02580e1e49', 'Su aplicación exclusiva a delitos menores.', false, 'Incorrecto. La justicia transicional se activa ante violaciones graves o masivas, no delitos menores.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4150a48a-e0ea-4a0e-9ad4-cc5903d85b1c', 'a3044ab9-5484-48ed-a246-9a02580e1e49', 'Su renuncia a investigar crímenes graves.', false, 'Incorrecto. No renuncia a investigar; prioriza y articula responsabilidades.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2b7e04c4-96fc-456a-87ff-e998caee132c', 'a3044ab9-5484-48ed-a246-9a02580e1e49', 'Su respuesta integral a daños masivos mediante mecanismos judiciales y no judiciales.', true, 'Correcto. Combina verdad, justicia, reparación, memoria, reformas y no repetición.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('960938df-d1ce-472a-808e-786a634d898f', 'a3044ab9-5484-48ed-a246-9a02580e1e49', 'Su eliminación de toda sanción para responsables.', false, 'Incorrecto. Puede incluir sanciones restaurativas y restricciones verificables.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7019427d-822e-44a0-bdbf-955e2e239f67', '7f9b51f5-9086-49d6-ad86-13f8a168028f', 'Porque reemplaza la reparación material.', false, 'Incorrecto. La verdad complementa, pero no reemplaza, la reparación.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('af116d57-1786-49da-900b-cbc33737532c', '7f9b51f5-9086-49d6-ad86-13f8a168028f', 'Porque esclarece hechos, patrones, responsabilidades e impactos negados.', true, 'Correcto. Permite reconocer daños y transformar condiciones que hicieron posible la violencia.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c3d0406c-655f-4cc2-aaf1-3d08c5240247', '7f9b51f5-9086-49d6-ad86-13f8a168028f', 'Porque impide que las víctimas participen en el proceso.', false, 'Incorrecto. La verdad transicional debe incorporar voces de víctimas con garantías.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('38ebc9d0-ba38-41eb-a4e0-11696d37eff5', '7f9b51f5-9086-49d6-ad86-13f8a168028f', 'Porque solo sirve para producir archivos administrativos.', false, 'Incorrecto. Los archivos pueden apoyar, pero la verdad tiene función pública y reparadora.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('979100f4-0f58-4c4a-9585-f82d2a77a853', '5ac68bb8-6082-466a-afe9-cf996932f967', 'Aceptar una culpa mínima sin aportar información.', false, 'Incorrecto. Un reconocimiento parcial o estratégico no satisface los derechos de las víctimas.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5bf1f956-8f25-4547-8976-d8b41976e45f', '5ac68bb8-6082-466a-afe9-cf996932f967', 'Evitar consecuencias jurídicas por haber participado en un acuerdo.', false, 'Incorrecto. La transición no elimina consecuencias; las reorganiza bajo criterios verificables.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2c583efa-d914-484e-9076-b92289ac8cba', '5ac68bb8-6082-466a-afe9-cf996932f967', 'Trasladar toda obligación de reparación al Estado.', false, 'Incorrecto. El Estado tiene obligaciones, pero los responsables deben contribuir a verdad y reparación.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('de0573cd-ef40-4540-a356-b0f0827834fd', '5ac68bb8-6082-466a-afe9-cf996932f967', 'Aportar verdad, asumir consecuencias y contribuir a reparar el daño.', true, 'Correcto. La responsabilidad exige seriedad, proporcionalidad y seguimiento.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3cea009d-cbe4-408c-b743-d7ec6b115ad6', 'ff55c1ea-0832-42c6-b9ef-563aec33fd9d', 'Transformar condiciones que permitieron la violencia.', true, 'Correcto. Buscan prevenir nuevos ciclos de victimización mediante reformas y protección.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('da163aaa-4102-4a3d-93d7-4e824a39c1a5', 'ff55c1ea-0832-42c6-b9ef-563aec33fd9d', 'Aplazar indefinidamente la reparación.', false, 'Incorrecto. La no repetición complementa, no aplaza, reparación y verdad.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('075dc9d9-9b53-4d45-94d9-74d10170e1ae', 'ff55c1ea-0832-42c6-b9ef-563aec33fd9d', 'Sustituir la verdad por promesas generales.', false, 'Incorrecto. Deben convertirse en acciones medibles, no en promesas vacías.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('de6f634a-970f-4612-9f26-a30831185b78', 'ff55c1ea-0832-42c6-b9ef-563aec33fd9d', 'Eliminar la memoria histórica para facilitar convivencia.', false, 'Incorrecto. La memoria ayuda a identificar lo que no debe repetirse.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e0c1cb27-da12-4cba-9c07-033c75417475', 'c6a69d18-85b1-4d01-8a82-19e3d098541b', 'Aumenta automáticamente la legitimidad social.', false, 'Incorrecto. La legitimidad requiere comprensión y diálogo situado.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8cc0a3db-6610-44d5-b7b9-8fb24fccef32', 'c6a69d18-85b1-4d01-8a82-19e3d098541b', 'Se resuelven todas las expectativas de las víctimas.', false, 'Incorrecto. Las expectativas se gestionan con información clara y participación.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3985eda0-b218-4249-929a-361a93953893', 'c6a69d18-85b1-4d01-8a82-19e3d098541b', 'Puede producir desconfianza, rumores y baja apropiación comunitaria.', true, 'Correcto. La distancia entre institución y comunidad debilita confianza en el proceso.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('333192fa-4eb0-438b-acf5-f5a8c608a6d0', 'c6a69d18-85b1-4d01-8a82-19e3d098541b', 'Evita la necesidad de pedagogía pública.', false, 'Incorrecto. La pedagogía es indispensable para explicar límites, derechos y rutas.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4b43b0d2-fa52-488e-9cd2-d5fbae4c2ac3', '33aeec9e-bfde-479a-8159-9b665a3a8845', 'Asignar la misma consecuencia a todos los actores sin analizar conductas.', false, 'Incorrecto. La proporcionalidad exige diferenciar roles y gravedad.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('69b9354e-5d54-48e2-9b66-13fa810b632a', '33aeec9e-bfde-479a-8159-9b665a3a8845', 'Distinguir niveles de mando, participación, omisión y aporte a la verdad.', true, 'Correcto. Permite priorizar patrones, sanciones y tratamientos según responsabilidad y verdad aportada.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d85a59bf-eba5-48c3-a591-497dd3641626', '33aeec9e-bfde-479a-8159-9b665a3a8845', 'Eliminar la responsabilidad de máximos responsables.', false, 'Incorrecto. Los máximos responsables son centrales en la priorización transicional.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('07ce931d-30f0-4c1b-bd53-03222043635e', '33aeec9e-bfde-479a-8159-9b665a3a8845', 'Reducir el análisis a testimonios sin contraste.', false, 'Incorrecto. La verdad debe contrastarse con pruebas, víctimas y contexto.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('878183db-829f-433c-bb02-382f8d61ceee', '5f772fbd-313e-433f-9a72-08c6fea03997', 'Devolver siempre a la víctima exactamente al estado anterior.', false, 'Incorrecto. Algunas pérdidas son irreversibles; la reparación busca dignificar y reconstruir condiciones.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0c3ab305-0347-4810-a5c7-434b832c1c60', '5f772fbd-313e-433f-9a72-08c6fea03997', 'Limitar la respuesta a indemnización económica.', false, 'Incorrecto. La indemnización es una medida posible, pero no suficiente.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ead76428-546d-4181-9ba8-9b8b8204e61e', '5f772fbd-313e-433f-9a72-08c6fea03997', 'Evitar cambios territoriales para no alterar el contexto.', false, 'Incorrecto. La reparación transformadora atiende causas y condiciones territoriales.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7e559d94-6f53-44ca-a468-0e0fbaad8217', '5f772fbd-313e-433f-9a72-08c6fea03997', 'Responder al daño y modificar condiciones de exclusión que aumentaron vulnerabilidades.', true, 'Correcto. Conecta reparación con ciudadanía, derechos y no repetición.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4d357c86-2d70-4bb8-bf7d-bcd66b75e42f', 'fdbacd52-95b2-4c88-a7e3-3907cdba4e36', 'Porque también requiere participación, eficacia, coherencia y cumplimiento verificable.', true, 'Correcto. La legalidad debe traducirse en prácticas comprensibles y justas para la sociedad.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('275a239d-cc9c-4757-bfb4-93b0d95e1a16', 'fdbacd52-95b2-4c88-a7e3-3907cdba4e36', 'Porque las normas son irrelevantes en justicia transicional.', false, 'Incorrecto. Las normas son necesarias, pero no suficientes.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('62adb6ea-0f35-452c-a27e-3a896ab74010', 'fdbacd52-95b2-4c88-a7e3-3907cdba4e36', 'Porque basta con que los comparecientes acepten el proceso.', false, 'Incorrecto. La aceptación de comparecientes no sustituye derechos de víctimas.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b16c35d2-3d13-46ca-aa1e-89fc1ababe26', 'fdbacd52-95b2-4c88-a7e3-3907cdba4e36', 'Porque la opinión de las víctimas no afecta la confianza pública.', false, 'Incorrecto. La percepción de víctimas y comunidades influye en la credibilidad del sistema.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7c3e70ec-00ba-4fe6-ad66-205acf23045b', '624cc81c-9193-42fc-ad66-1b7dbcd0c346', 'Cerrar el debate mediante una versión única impuesta.', false, 'Incorrecto. La verdad transicional debe ser rigurosa, plural y contrastada.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2ad2b564-396b-4398-9e6a-e8c8a42b6713', '624cc81c-9193-42fc-ad66-1b7dbcd0c346', 'Sustituir la investigación judicial por memoria informal.', false, 'Incorrecto. La memoria y la verdad judicial pueden complementarse.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('02a90f5b-b099-4c48-863b-64a7019650cf', '624cc81c-9193-42fc-ad66-1b7dbcd0c346', 'Nombrar hechos, patrones e impactos para enfrentar negación y orientar reparación.', true, 'Correcto. Permite reconocer daños y activar medidas de no repetición.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('64fd9d95-a11a-4df9-a700-bd38d359933e', '624cc81c-9193-42fc-ad66-1b7dbcd0c346', 'Evitar responsabilidades institucionales.', false, 'Incorrecto. La verdad también examina omisiones, estructuras y fallas institucionales.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('abc12fd2-5558-47da-885b-69daf3d2e285', 'a9ffc42d-fd80-4c0f-9afb-a1da29e3d972', 'Ser una actividad aislada sin supervisión.', false, 'Incorrecto. La falta de supervisión debilita la credibilidad de la sanción.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9b0518a3-6acb-4627-a761-81d0c67036a4', 'a9ffc42d-fd80-4c0f-9afb-a1da29e3d972', 'Tener proporcionalidad, restricciones efectivas, reparación y verificación.', true, 'Correcto. Debe comunicar reproche, exigir verdad y producir efectos reparadores verificables.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a0355974-ecb2-4270-b1f2-2b62c81e7f78', 'a9ffc42d-fd80-4c0f-9afb-a1da29e3d972', 'Depender solo de la voluntad del responsable.', false, 'Incorrecto. La justicia transicional requiere obligaciones, no voluntarismo.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('17312eb4-c5a0-4b15-8c8e-ed31e2528594', 'a9ffc42d-fd80-4c0f-9afb-a1da29e3d972', 'Omitir la participación de las víctimas para evitar conflictos.', false, 'Incorrecto. La participación de víctimas orienta pertinencia y legitimidad.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a53e70c3-f8ab-4ba6-aec3-e2f1c8681fb3', '94102d2d-343a-4694-930b-4dd85ef073af', 'Caracterizar el daño, los sujetos afectados y el contexto territorial.', true, 'Correcto. Sin diagnóstico, no hay correspondencia entre daño y medida.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3349d988-d568-4de7-bd03-a0e75ce5af1a', '94102d2d-343a-4694-930b-4dd85ef073af', 'Escoger una medida simbólica antes de escuchar a las víctimas.', false, 'Incorrecto. Las medidas simbólicas pueden ser valiosas si surgen de participación y verdad.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('de018022-26b8-4540-add6-e823670df8f5', '94102d2d-343a-4694-930b-4dd85ef073af', 'Entregar el mismo beneficio a todas las personas.', false, 'Incorrecto. La igualdad formal puede ocultar daños diferenciales.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f08f5426-73a7-4ad2-a3d9-9ceba40f8264', '94102d2d-343a-4694-930b-4dd85ef073af', 'Definir una ceremonia pública sin verificar responsabilidades.', false, 'Incorrecto. La satisfacción requiere reconocimiento real y diseño cuidadoso.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1b1bb1e2-b058-4ea5-aa74-94d7f6449cb4', 'd57383a7-e275-4e97-9651-7fc609c9e872', 'La asistencia siempre exige reconocimiento de responsabilidad.', false, 'Incorrecto. La asistencia responde a urgencias, no necesariamente a responsabilidad por daño.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('259ce03f-31fc-46d6-b9a8-b62d50c411db', 'd57383a7-e275-4e97-9651-7fc609c9e872', 'La reparación solo atiende necesidades urgentes.', false, 'Incorrecto. La reparación puede incluir respuestas de largo plazo, simbólicas y transformadoras.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('47b703e9-0ae5-47a7-936e-1d2a32118797', 'd57383a7-e275-4e97-9651-7fc609c9e872', 'La reparación reconoce un daño injusto y exige medidas específicas frente a ese daño.', true, 'Correcto. Parte de la condición de víctima como sujeto de derechos.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0c03ec05-5ca3-4862-8d93-00df4720e0f1', 'd57383a7-e275-4e97-9651-7fc609c9e872', 'La asistencia y la reparación son idénticas en justicia transicional.', false, 'Incorrecto. Confundirlas debilita la centralidad de las víctimas.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d45998d9-b06d-4548-bc21-e7838ca86478', '0ab02532-7bc0-4be5-9319-380a04247210', 'Cuando se construye con participación informada de víctimas.', false, 'Incorrecto. La participación reduce riesgos y mejora pertinencia.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('79e8d0d2-7e1a-443b-8444-e2859e5ef048', '0ab02532-7bc0-4be5-9319-380a04247210', 'Cuando reconoce públicamente la dignidad de quienes sufrieron.', false, 'Incorrecto. El reconocimiento público puede dignificar si es auténtico.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('df3fa52c-9895-45e3-84d2-0c4eb966a45d', '0ab02532-7bc0-4be5-9319-380a04247210', 'Cuando se articula con verdad y memoria.', false, 'Incorrecto. La verdad y la memoria fortalecen el sentido reparador.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9e2e736b-9a92-49e5-b9ed-bc200604ce2f', '0ab02532-7bc0-4be5-9319-380a04247210', 'Cuando se impone como ceremonia vacía sin consentimiento ni relación con el daño.', true, 'Correcto. Una medida simbólica impuesta puede profundizar dolor y desconfianza.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('996c4ffe-f5c4-419d-b323-5c389a5a17d6', '299c10ee-8b39-414b-8c1b-4bdfe031f909', 'Porque ignora completamente a las personas afectadas.', false, 'Incorrecto. La reparación colectiva no excluye daños individuales.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4516079a-c9a5-44d3-8c04-136cf62092f9', '299c10ee-8b39-414b-8c1b-4bdfe031f909', 'Porque atiende daños sobre identidad, tejido social, territorio y organización comunitaria.', true, 'Correcto. Reconoce afectaciones compartidas que dañan formas de vida común.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5adaaa15-d9d7-40c7-861b-e616e7d8164c', '299c10ee-8b39-414b-8c1b-4bdfe031f909', 'Porque solo entrega indemnizaciones monetarias.', false, 'Incorrecto. Puede incluir medidas materiales, simbólicas, psicosociales y territoriales.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('22b8df17-c877-4f5e-bbc0-25dd40885db7', '299c10ee-8b39-414b-8c1b-4bdfe031f909', 'Porque elimina los enfoques diferenciales internos.', false, 'Incorrecto. Debe considerar diferencias de género, edad, etnia y condiciones internas.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2418a9d1-5091-46fb-9494-17f4434299f7', '9b5ae65a-aaea-4208-b567-f1a174b08539', 'La cantidad de comunicados institucionales publicados.', false, 'Incorrecto. La comunicación es útil si acompaña resultados reales.', 0, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('6dcdd395-7fff-40d3-8db4-2e5912f98e79', '9b5ae65a-aaea-4208-b567-f1a174b08539', 'La ausencia de seguimiento después de la implementación.', false, 'Incorrecto. Sin seguimiento no se verifica efecto reparador.', 1, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a942bd43-aaef-44e9-80f3-034b69a16b2d', '9b5ae65a-aaea-4208-b567-f1a174b08539', 'La correspondencia entre daño, participación, viabilidad y evidencia de cumplimiento.', true, 'Correcto. Estos criterios permiten diferenciar reparación efectiva de cumplimiento formal.', 2, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d090591d-2b0c-43cc-82f0-871e598dede5', '9b5ae65a-aaea-4208-b567-f1a174b08539', 'La rapidez con que se anuncia sin consultar a la comunidad.', false, 'Incorrecto. La rapidez no sustituye participación ni pertinencia.', 3, '2026-07-30 16:43:35.591755+00', '2026-07-30 16:43:35.591755+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c9a67859-d2d2-4e8f-8d5f-d05c31aafe0f', 'd2d7fb75-1919-4324-b8c8-e37b94e43f53', 'Aplicar una sola respuesta uniforme a todas las víctimas.', false, 'Incorrecto. Los daños no son homogéneos y requieren respuestas diferenciadas.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e773b38e-f9b6-4a8c-a25b-995952f28dc7', 'd2d7fb75-1919-4324-b8c8-e37b94e43f53', 'Separar la reparación de la verdad y la justicia.', false, 'Incorrecto. La reparación se articula con verdad, justicia y no repetición.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d2ee9f58-4b84-42b7-b601-7738be8cb534', 'd2d7fb75-1919-4324-b8c8-e37b94e43f53', 'Ordenar medidas según la naturaleza material, simbólica, psicosocial o colectiva del daño.', true, 'Correcto. Ayuda a seleccionar medidas pertinentes y verificables.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e7528f73-8b92-4d64-b4b6-61bad3281326', 'd2d7fb75-1919-4324-b8c8-e37b94e43f53', 'Convertir toda reparación en indemnización monetaria.', false, 'Incorrecto. La indemnización no agota los tipos de reparación.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f2a564a1-20ea-427f-9f17-67f7e498f0b4', '8a603376-5350-47b0-b4f8-b3eea40c7a1b', 'Busca restablecer derechos, bienes o condiciones alteradas por la victimización.', true, 'Correcto. Procura devolver o recomponer aquello arrebatado, cuando es posible.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1b021a54-05e2-4738-b09b-f63301721b08', '8a603376-5350-47b0-b4f8-b3eea40c7a1b', 'Sustituye toda reparación simbólica.', false, 'Incorrecto. La restitución puede necesitar satisfacción, rehabilitación y no repetición.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ba6408a4-8fbf-4a01-8b61-eedb33e1f819', '8a603376-5350-47b0-b4f8-b3eea40c7a1b', 'Consiste únicamente en pedir disculpas públicas.', false, 'Incorrecto. Las disculpas son medidas de satisfacción, no restitución.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('193329e1-ea67-4142-82c8-17086fb25117', '8a603376-5350-47b0-b4f8-b3eea40c7a1b', 'Se completa con una decisión formal aunque no existan garantías reales.', false, 'Incorrecto. Sin seguridad y sostenibilidad, la restitución puede fracasar.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3aedd660-450a-47c8-8b5b-f0999af8220d', '25717542-f355-49c6-a6bb-98d699dc83dd', 'Reconocer que puede aliviar pérdidas cuantificables.', false, 'Incorrecto. Ese reconocimiento es correcto, aunque limitado.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0ec72d1e-6562-427e-a2f0-bae729352ca2', '25717542-f355-49c6-a6bb-98d699dc83dd', 'Presentarla como reparación total y cierre definitivo del proceso.', true, 'Correcto. La indemnización no compra el sufrimiento ni sustituye verdad o garantías futuras.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0c0be895-306f-4e5d-ab1b-7c0ff99c438f', '25717542-f355-49c6-a6bb-98d699dc83dd', 'Relacionarla con daños materiales o morales.', false, 'Incorrecto. La indemnización puede responder a pérdidas cuantificables.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0eb19629-cf72-4298-b82b-e8506b169d77', '25717542-f355-49c6-a6bb-98d699dc83dd', 'Articularla con rehabilitación y satisfacción.', false, 'Incorrecto. La articulación con otras medidas fortalece su sentido reparador.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b05a026e-d2f2-46e5-b761-2ebb95eb1559', 'be7e76fb-106f-4a99-a0be-4e8f48e3788f', 'Un trámite breve y estandarizado para todas las víctimas.', false, 'Incorrecto. La rehabilitación debe respetar tiempos y necesidades diferenciadas.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('eb3ee40a-3184-4a03-88d3-38cdd1d82a3c', 'be7e76fb-106f-4a99-a0be-4e8f48e3788f', 'Únicamente atención médica sin dimensión social.', false, 'Incorrecto. El daño puede afectar cuerpo, emociones, vínculos y capacidades sociales.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e5192507-cb3a-4c57-9a17-4e94530d83a0', 'be7e76fb-106f-4a99-a0be-4e8f48e3788f', 'La eliminación de acompañamiento jurídico.', false, 'Incorrecto. El acompañamiento jurídico puede ser parte de la rehabilitación integral.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('90d01336-c1f4-4bce-afa2-1370e6742ac7', 'be7e76fb-106f-4a99-a0be-4e8f48e3788f', 'Atención médica, psicológica, psicosocial, jurídica y social con continuidad.', true, 'Correcto. Busca reconstruir bienestar y autonomía después del daño.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('64e7d361-71d8-4ad2-a36c-c326c2d70b45', 'aa11cb76-bd07-41aa-9206-ff0bb8411186', 'Repetir ceremonias públicas cada año sin cambios institucionales.', false, 'Incorrecto. Las ceremonias pueden apoyar memoria, pero no reemplazan cambios.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9603a1ff-c4e9-4a4c-928a-a669a692b99c', 'aa11cb76-bd07-41aa-9206-ff0bb8411186', 'Aplazar reformas porque pertenecen a otro campo.', false, 'Incorrecto. La no repetición requiere reformas, protección y aprendizaje institucional.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4edcb77f-1709-4579-b3a4-f984e06f59bc', 'aa11cb76-bd07-41aa-9206-ff0bb8411186', 'Transformar condiciones que permitieron la violencia mediante acciones verificables.', true, 'Correcto. Previene nuevos daños al actuar sobre causas y riesgos.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('9a9c98f1-7fef-463b-9628-5f6e8da78e31', 'aa11cb76-bd07-41aa-9206-ff0bb8411186', 'Limitarse a declaraciones de buena voluntad.', false, 'Incorrecto. Las promesas sin responsables ni indicadores son insuficientes.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7e7f8c22-9384-4f73-b673-fbb022208012', '331b8e68-6e84-49c4-9cde-1afe04612336', 'Que la víctima puede exigir medidas proporcionales frente al daño sufrido.', true, 'Correcto. Reconoce a las víctimas como titulares de derechos y no beneficiarias pasivas.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('926876f7-ca96-4564-86c9-96b27ceb39e6', '331b8e68-6e84-49c4-9cde-1afe04612336', 'Que depende de la caridad institucional.', false, 'Incorrecto. La reparación no puede depender de voluntarismo estatal.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('58a4231f-34b2-4cff-ba46-435674150fd5', '331b8e68-6e84-49c4-9cde-1afe04612336', 'Que solo procede si hay recursos sobrantes.', false, 'Incorrecto. La disponibilidad de recursos no elimina obligaciones de respuesta.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e997beac-c7e1-4ac5-af01-d9fc7590bf6f', '331b8e68-6e84-49c4-9cde-1afe04612336', 'Que excluye toda participación de responsables.', false, 'Incorrecto. Los responsables pueden tener deberes de verdad y contribución reparadora.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0c8261ce-497f-4d26-b4e6-a0dd137f5791', '042eae95-28ed-480b-8fba-30317a183f19', 'Un daño exclusivamente patrimonial.', false, 'Incorrecto. El daño patrimonial es solo una dimensión posible.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('00502071-713f-4fc6-b730-b91f63a7b142', '042eae95-28ed-480b-8fba-30317a183f19', 'La variedad de afectaciones materiales, emocionales, territoriales, culturales y políticas.', true, 'Correcto. Permite seleccionar medidas integrales y pertinentes.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7f169adf-42f3-4282-a83c-dd285772cf69', '042eae95-28ed-480b-8fba-30317a183f19', 'Un concepto que elimina la necesidad de diagnóstico.', false, 'Incorrecto. Exige diagnóstico sensible y no revictimizante.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('017bd88b-8ca9-4e5c-ba1d-eee61adcf29f', '042eae95-28ed-480b-8fba-30317a183f19', 'Una categoría aplicable solo a instituciones estatales.', false, 'Incorrecto. Aplica a personas, comunidades, territorios y proyectos de vida.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e2841289-5d87-473d-83a7-ba231b492f55', '0ff97464-1810-48de-933e-afb528b869f8', 'Porque permite prometer todas las medidas solicitadas.', false, 'Incorrecto. Participar no significa satisfacer automáticamente toda expectativa.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4161325d-42a4-4e4a-bc1f-36f440a3e649', '0ff97464-1810-48de-933e-afb528b869f8', 'Porque sustituye el análisis técnico por emociones.', false, 'Incorrecto. La participación complementa el análisis técnico y ético.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('dbe0828d-9218-4c51-9d50-c8ad7eddf683', '0ff97464-1810-48de-933e-afb528b869f8', 'Porque evita identificar límites institucionales.', false, 'Incorrecto. También exige explicar límites, tiempos y responsabilidades.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a19a9814-3ddd-4d9c-bbc6-fac0b179f89e', '0ff97464-1810-48de-933e-afb528b869f8', 'Porque conecta la medida con la experiencia real del daño y evita diseños impuestos.', true, 'Correcto. Sin escucha efectiva, la reparación puede convertirse en trámite o revictimización.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4babdae8-9895-421e-a54e-9fa0f4d94141', '0d7edc45-2f59-46b1-9a0d-c02184ec55b9', 'Que produce cambios verificables en la vida de las víctimas.', false, 'Incorrecto. Eso corresponde a reparación efectiva.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a8df172c-8542-413e-ada9-373f3b9433fc', '0d7edc45-2f59-46b1-9a0d-c02184ec55b9', 'Que articula responsabilidades, recursos y seguimiento.', false, 'Incorrecto. La articulación fortalece la reparación real.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('67e1f83a-cac6-4a21-9a5e-e53c26092b98', '0d7edc45-2f59-46b1-9a0d-c02184ec55b9', 'Que aparece en normas o planes, pero no genera efectos reales de dignificación.', true, 'Correcto. La declaración sin implementación puede frustrar expectativas y erosionar confianza.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3820f3c6-7f12-4c59-bb49-cc8d35ee4397', '0d7edc45-2f59-46b1-9a0d-c02184ec55b9', 'Que respeta la centralidad de las víctimas.', false, 'Incorrecto. La centralidad de víctimas exige participación y cumplimiento.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b3c9b801-5b99-49c4-b9d9-dd7756a2bc7a', 'd9c27b8e-b257-4597-bd52-b8a1a6da1c03', 'Solo por el número de actividades realizadas.', false, 'Incorrecto. La cantidad no muestra por sí sola efectos reparadores.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e59ec406-9b78-4d46-93c6-0d065e87a04a', 'd9c27b8e-b257-4597-bd52-b8a1a6da1c03', 'Por su correspondencia con el daño, participación, enfoque diferencial, sostenibilidad y seguimiento.', true, 'Correcto. Estos criterios permiten valorar si hay reparación efectiva.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7754201e-466b-4e50-a2d0-e04ed92ae64d', 'd9c27b8e-b257-4597-bd52-b8a1a6da1c03', 'Únicamente por el presupuesto ejecutado.', false, 'Incorrecto. El presupuesto importa, pero no basta para medir dignificación o no repetición.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('533e7414-476e-4036-91df-a35cb8aa7193', 'd9c27b8e-b257-4597-bd52-b8a1a6da1c03', 'Por la rapidez con que se cierra el expediente.', false, 'Incorrecto. Cerrar expedientes no equivale a reparar integralmente.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('95723a12-8eea-4e93-9c90-4c0533fb8a30', '1fb9c2d3-3713-4311-9d20-d5cfe4b245ec', 'Llegar al territorio con justicia, servicios, participación, seguridad y garantía de derechos.', true, 'Correcto. La paz territorial requiere Estado legítimo, permanente y coordinado.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('c161634b-d4b3-41fd-ae0c-aefbc4255028', '1fb9c2d3-3713-4311-9d20-d5cfe4b245ec', 'Realizar operativos temporales sin continuidad.', false, 'Incorrecto. Los operativos aislados no construyen confianza sostenida.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e6767c90-148f-4784-9c2b-ab875a8008ed', '1fb9c2d3-3713-4311-9d20-d5cfe4b245ec', 'Reemplazar la participación social por control armado.', false, 'Incorrecto. La participación social fortalece legitimidad y prevención.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('29877a15-c686-4d5f-931b-529c0b3c6dd2', '1fb9c2d3-3713-4311-9d20-d5cfe4b245ec', 'Concentrar la acción estatal solo en fuerza pública.', false, 'Incorrecto. La seguridad debe articularse con derechos y servicios.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('46104be5-2b8e-4569-934e-679588c17592', 'b6e12b52-1087-4690-a733-d193a1505681', 'Porque impide toda actuación de las instituciones de seguridad.', false, 'Incorrecto. El control civil no paraliza, sino orienta la acción bajo reglas democráticas.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e94caee6-661e-4dff-b93f-36ff7762030c', 'b6e12b52-1087-4690-a733-d193a1505681', 'Porque elimina la necesidad de rendición de cuentas.', false, 'Incorrecto. La rendición de cuentas es parte esencial del control civil.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('3de5cb32-c6b8-4b13-a6de-67eef8b169fa', 'b6e12b52-1087-4690-a733-d193a1505681', 'Porque concentra decisiones en mandos sin supervisión.', false, 'Incorrecto. La supervisión previene abusos y fortalece legitimidad.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('709fabb2-b474-4dfb-8939-563048bb5ad5', 'b6e12b52-1087-4690-a733-d193a1505681', 'Porque somete el uso legítimo de la fuerza a límites democráticos y vigilancia pública.', true, 'Correcto. Incluye dirección política, control judicial, disciplinario y participación ciudadana.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4e400ee2-04bf-4e20-b1e6-ac3c39e0d783', '6a1f6695-feec-44db-9dd9-8d07d3a0bf33', 'Se fortalecen automáticamente los derechos humanos.', false, 'Incorrecto. Los derechos requieren criterios de proporcionalidad, control y prevención.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('bbaf704f-4f54-4806-94e7-20f8d35f6a85', '6a1f6695-feec-44db-9dd9-8d07d3a0bf33', 'Se incorporan indicadores de confianza comunitaria.', false, 'Incorrecto. Ese enfoque ampliado sería más compatible con seguridad humana.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7e512531-cc8c-42c4-82fa-992c7973d335', '6a1f6695-feec-44db-9dd9-8d07d3a0bf33', 'Pueden producirse incentivos distorsionados que descuiden protección de la población.', true, 'Correcto. La reforma debe revisar qué se mide, premia y tolera institucionalmente.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('680e0f33-b5a3-4658-9b66-da92c0aa5533', '6a1f6695-feec-44db-9dd9-8d07d3a0bf33', 'Se garantiza la no repetición de abusos.', false, 'Incorrecto. La no repetición exige cambios verificables, no indicadores estrechos.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('01960e86-2af6-4d92-8772-0957237bef7d', 'dae27b74-173f-41ed-952b-f6f1dd4b5a62', 'La verdad judicial solo sirve para cerrar expedientes.', false, 'Incorrecto. La verdad también tiene función preventiva y pedagógica.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ed035b30-d301-4373-8a62-be9d6ba89770', 'dae27b74-173f-41ed-952b-f6f1dd4b5a62', 'Los hallazgos sobre patrones y fallas deben alimentar cambios en protocolos, controles e incentivos.', true, 'Correcto. La justicia transicional debe convertirse en aprendizaje institucional.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2527fbf6-7d67-45fd-9b31-e2770991c6f0', 'dae27b74-173f-41ed-952b-f6f1dd4b5a62', 'La reforma debe ignorar lo ocurrido para evitar tensiones.', false, 'Incorrecto. Ignorar patrones puede permitir repetición de daños.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7f43815d-c570-428a-b64e-19a6060837ca', 'dae27b74-173f-41ed-952b-f6f1dd4b5a62', 'Las instituciones no pueden aprender de decisiones transicionales.', false, 'Incorrecto. Las decisiones pueden orientar formación, supervisión y rendición de cuentas.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fd781b43-5ed4-440f-8b73-4c61f9803079', '34e101e7-94d4-4e9c-aad9-86264dfe4781', 'Que la eficacia exige actuar por fuera de la ley.', false, 'Incorrecto. La arbitrariedad debilita legitimidad y puede reproducir violencia.', 0, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('89237a25-f260-4017-bbba-7c8833ab3716', '34e101e7-94d4-4e9c-aad9-86264dfe4781', 'Que la seguridad puede operar sin control judicial.', false, 'Incorrecto. El control judicial protege derechos y confianza pública.', 1, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e9e70dce-b8b5-4632-8e0d-de4e44a8cfdf', '34e101e7-94d4-4e9c-aad9-86264dfe4781', 'Que toda autoridad debe someterse a normas, derechos y procedimientos legítimos.', true, 'Correcto. El respeto por la ley fortalece seguridad democrática y no repetición.', 2, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('7aefb49e-de37-4921-a712-21db9fa4bc5f', '34e101e7-94d4-4e9c-aad9-86264dfe4781', 'Que las garantías son obstáculos para la paz.', false, 'Incorrecto. Las garantías permiten una paz compatible con derechos.', 3, '2026-07-30 16:45:05.000945+00', '2026-07-30 16:45:05.000945+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f61f63c0-1d4b-4027-b2ee-8ce2642aa185', 'a47cb78d-e6a2-444b-9b48-dffa012cf521', 'La ausencia temporal de debates públicos.', false, 'Incorrecto. El debate democrático es compatible con la paz.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e3ca96b4-52cf-44ab-ba53-4bfb470121dd', 'a47cb78d-e6a2-444b-9b48-dffa012cf521', 'La capacidad de tramitar conflictos sin retorno a violencia sistemática.', true, 'Correcto. Implica instituciones legítimas, derechos, participación y prevención.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d59469a1-0fdf-4c4a-818c-7ef7ba8f9bcd', 'a47cb78d-e6a2-444b-9b48-dffa012cf521', 'La eliminación de toda diferencia social.', false, 'Incorrecto. La paz no elimina diferencias; crea canales no violentos para tramitarlas.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4c390c59-3817-48f1-b50d-acd89b1b35ea', 'a47cb78d-e6a2-444b-9b48-dffa012cf521', 'La firma de un acuerdo sin implementación posterior.', false, 'Incorrecto. El acuerdo abre una posibilidad, pero no asegura sostenibilidad por sí mismo.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('579c7cea-36e6-4c73-8bb3-41d0b4e949b6', '80e38964-f24a-46c3-8739-5753cbb01356', 'Porque la justicia transicional impide prevenir riesgos.', false, 'Incorrecto. La justicia transicional busca precisamente prevenir y transformar riesgos.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2b214b8e-4b03-439e-a303-93c203887973', '80e38964-f24a-46c3-8739-5753cbb01356', 'Porque las víctimas dejan de tener derechos después del acuerdo.', false, 'Incorrecto. Los derechos de las víctimas continúan orientando verdad, reparación y no repetición.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ffd522a4-e75a-4232-8fe4-21587774cc67', '80e38964-f24a-46c3-8739-5753cbb01356', 'Porque pueden persistir amenazas, economías ilegales, desigualdades y actores armados.', true, 'Correcto. La transición puede ser desigual y territorialmente frágil.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('bf75c4d3-b767-4eb9-92e7-fb43e383b381', '80e38964-f24a-46c3-8739-5753cbb01356', 'Porque la paz solo existe cuando no hay instituciones.', false, 'Incorrecto. La institucionalidad legítima es condición para sostener la paz.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('68a8d746-393f-420a-bfc4-92a38b36b472', '44484371-a000-4b24-8324-95f099894f70', 'Seguridad, ingresos, educación, apoyo psicosocial y aceptación comunitaria.', true, 'Correcto. La reincorporación es social, económica, jurídica y comunitaria.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1455a535-5c1a-4523-850a-31357e5b2b64', '44484371-a000-4b24-8324-95f099894f70', 'Solo la entrega de un empleo individual.', false, 'Incorrecto. El empleo puede ayudar, pero no cubre seguridad, reconocimiento y redes sociales.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('09417f7d-c281-42db-9e49-56eb45ad08f2', '44484371-a000-4b24-8324-95f099894f70', 'Aislar a excombatientes de las comunidades receptoras.', false, 'Incorrecto. La integración territorial reduce riesgos de estigmatización y rearme.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('db7d6974-1a32-48f8-98d4-e9b5ded615fe', '44484371-a000-4b24-8324-95f099894f70', 'Ignorar a víctimas para evitar tensiones.', false, 'Incorrecto. Debe equilibrar garantías a firmantes con derechos de víctimas y comunidades.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('71fb6779-2ea5-457d-b80e-de87c2f1f496', 'ba700fc3-8dc9-451c-88f5-8747fc99edf9', 'Evalúa solo resultados militares.', false, 'Incorrecto. La seguridad humana amplía los indicadores más allá de lo militar.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e6c5de6f-af0c-4b1f-a4d7-65aeb4e87dd2', 'ba700fc3-8dc9-451c-88f5-8747fc99edf9', 'Reduce la protección a control armado.', false, 'Incorrecto. El control armado sin derechos puede generar temor y desconfianza.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('20cf282f-739d-490a-b8a1-aad6e7666fdf', 'ba700fc3-8dc9-451c-88f5-8747fc99edf9', 'Sustituye toda política social.', false, 'Incorrecto. No sustituye política social, la articula con prevención y protección.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b8e0f324-937d-45ce-9bcd-92de2453de21', 'ba700fc3-8dc9-451c-88f5-8747fc99edf9', 'Ubica la vida, dignidad y libertades de las personas como centro de la seguridad.', true, 'Correcto. Permite diseñar respuestas ante amenazas, reclutamiento, extorsión o desplazamiento.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('488a192b-76ad-4b94-9097-5fc7239739b1', '1d27f5c8-fec1-4be1-8f04-60945b98a644', 'Exigiendo obediencia sin resultados verificables.', false, 'Incorrecto. La confianza no se impone; se demuestra con coherencia.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('0653f06e-cdd2-468a-b6dd-5d093b058895', '1d27f5c8-fec1-4be1-8f04-60945b98a644', 'Cumpliendo compromisos, protegiendo derechos, escuchando y rindiendo cuentas.', true, 'Correcto. La comunidad confía cuando observa legalidad, eficacia y respeto.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('20fbe0ff-4d46-4e35-ba78-c5172af39409', '1d27f5c8-fec1-4be1-8f04-60945b98a644', 'Sustituyendo participación por decisiones centralizadas.', false, 'Incorrecto. La participación territorial mejora pertinencia y legitimidad.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('78d79c85-6e57-4ec4-a073-52cb3001eb90', '8d5da984-f4bc-4c13-a818-d310507180aa', 'Mejora la legitimidad porque reduce discusiones.', false, 'Incorrecto. La deliberación puede ser exigente, pero fortalece legitimidad.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('19219ab2-744e-403a-ba04-2f82d3f16a19', '8d5da984-f4bc-4c13-a818-d310507180aa', 'Garantiza reparación integral automática.', false, 'Incorrecto. La reparación integral exige correspondencia con daño y seguimiento.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f0da92af-0688-4d7f-8b0c-a94153f90735', '8d5da984-f4bc-4c13-a818-d310507180aa', 'Puede percibirse como formalidad administrativa sin sentido reparador.', true, 'Correcto. La ausencia de participación puede generar frustración y revictimización.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b0518f23-85fd-420b-8fc2-e2eea249f062', '8d5da984-f4bc-4c13-a818-d310507180aa', 'Sustituye la necesidad de seguridad territorial.', false, 'Incorrecto. Sin seguridad, cualquier proyecto puede exponer a participantes.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ffea1457-d27b-4095-b54c-e7ba84762f2a', '0d233900-5445-4ddc-8774-7acd985beeee', 'Porque la paz se experimenta en veredas, barrios, instituciones locales y comunidades concretas.', true, 'Correcto. El postconflicto se juega en contextos locales con actores y daños específicos.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('648905b7-4f24-44e4-8ed7-b3612037c883', '0d233900-5445-4ddc-8774-7acd985beeee', 'Porque todos los territorios tienen idénticos riesgos y capacidades.', false, 'Incorrecto. Las respuestas uniformes pueden fallar frente a realidades distintas.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2043cc44-88d8-4474-88e7-7f5c9d36fbc7', '0d233900-5445-4ddc-8774-7acd985beeee', 'Porque las políticas nacionales no necesitan adaptación.', false, 'Incorrecto. La adaptación territorial permite coherencia nacional y pertinencia local.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5df8344d-a456-4c1a-9209-05f69f8bdf1a', '0d233900-5445-4ddc-8774-7acd985beeee', 'Porque la presencia estatal debe limitarse a controles temporales.', false, 'Incorrecto. La presencia integral requiere permanencia y servicios, no solo controles.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f58931ac-09c4-4f79-b0f2-f0a34e671945', '41bb5b37-0b66-48ee-b6b0-7c6f106f90e8', 'Solo el número de reuniones realizadas.', false, 'Incorrecto. Las reuniones no indican por sí solas impacto territorial.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('4099381b-c0b9-4dfd-9893-6a564bda3682', '41bb5b37-0b66-48ee-b6b0-7c6f106f90e8', 'Únicamente los recursos ejecutados.', false, 'Incorrecto. La ejecución presupuestal no garantiza derechos ni confianza.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('24a4a797-f225-40d6-8842-821ac6e41f48', '41bb5b37-0b66-48ee-b6b0-7c6f106f90e8', 'La cantidad de comunicados institucionales.', false, 'Incorrecto. La comunicación debe acompañar resultados, no reemplazarlos.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('b2a55975-e1ae-4869-9c03-42f6f38a0bc1', '41bb5b37-0b66-48ee-b6b0-7c6f106f90e8', 'Protección, participación, reparación, confianza, reducción de amenazas y cumplimiento real.', true, 'Correcto. Los indicadores deben reflejar cambios en la vida cotidiana y compromisos verificables.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5a546739-4ede-425d-920f-5297c994f13a', '2e91dca8-c01b-450a-813f-77d704ca6c6d', 'Eliminar toda discusión sobre justicia.', false, 'Incorrecto. La discusión sobre justicia es necesaria en democracia.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('46e88814-1440-4225-920d-f752557ff1ae', '2e91dca8-c01b-450a-813f-77d704ca6c6d', 'Equilibrar justicia, estabilidad, verdad, reparación e incentivos de transición.', true, 'Correcto. La paz sostenible requiere tramitar tensiones sin sacrificar derechos.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('278298aa-5b39-407d-a047-83d3d78b7ec8', '2e91dca8-c01b-450a-813f-77d704ca6c6d', 'Renunciar a la memoria para evitar tensiones.', false, 'Incorrecto. La memoria ayuda a reconocer daños y prevenir repetición.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ed8d1905-3a45-44c6-9e8e-d136413dd2f8', '2e91dca8-c01b-450a-813f-77d704ca6c6d', 'Sustituir derechos por rapidez administrativa.', false, 'Incorrecto. La rapidez no puede anular dignidad ni garantías.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('df945c77-e2e9-47ed-b4be-2d591cb7946c', '850858ac-38b8-4625-b802-4500537326d3', 'Que sea incomprensible para las víctimas.', false, 'Incorrecto. La comprensión pública favorece legitimidad.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e0130473-65fd-4cef-aab2-f1a4bff10836', '850858ac-38b8-4625-b802-4500537326d3', 'Que no tenga seguimiento posterior.', false, 'Incorrecto. Sin seguimiento no se garantiza cumplimiento ni reparación.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1123aee0-81c2-4eff-a36d-58f07231255c', '850858ac-38b8-4625-b802-4500537326d3', 'Que conecte responsabilidad, daño, participación y acciones verificables.', true, 'Correcto. El vínculo entre daño y medida es esencial para la justicia restaurativa.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d0cf60f3-6b43-49f6-8e86-94322432799e', '850858ac-38b8-4625-b802-4500537326d3', 'Que ignore las necesidades del territorio.', false, 'Incorrecto. El enfoque territorial mejora pertinencia y sostenibilidad.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e25ddec3-9fc2-47e1-be60-c3f688ec5b65', 'aeaae122-2bcc-4f29-9910-91f9f41b26c0', 'Puede aumentar rechazo social, competencia por recursos y riesgo de retorno a ilegalidad.', true, 'Correcto. La inclusión debe ser territorial y sensible a víctimas y población local.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('f8749e93-46ac-4264-bd20-bc87c330e314', 'aeaae122-2bcc-4f29-9910-91f9f41b26c0', 'Garantiza reconciliación automática.', false, 'Incorrecto. La reconciliación exige procesos, garantías y beneficios compartidos.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8a110855-6383-4172-a897-07dd6e0f9310', 'aeaae122-2bcc-4f29-9910-91f9f41b26c0', 'Elimina amenazas de actores armados.', false, 'Incorrecto. La seguridad requiere medidas específicas frente a actores ilegales.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('305ed705-5774-462a-8e92-63eb5a8baec3', 'aeaae122-2bcc-4f29-9910-91f9f41b26c0', 'Asegura que no haya estigmatización.', false, 'Incorrecto. La estigmatización se reduce con pedagogía, participación y oportunidades.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('067d4c20-837b-4b91-bc9f-c21e2c4b80d1', '257ab555-97b1-4434-8a08-a92e780c8eb6', 'Esperar a que se reactive la violencia para actuar.', false, 'Incorrecto. La prevención exige anticipación, no reacción tardía.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('d32cc728-e4fc-4ecf-be11-9edd7e5c637d', '257ab555-97b1-4434-8a08-a92e780c8eb6', 'Registrar amenazas sin activar respuestas.', false, 'Incorrecto. El registro solo es útil si genera protección y acción institucional.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('2081d72f-2dd3-4c7f-80e3-d68b28f3a4f8', '257ab555-97b1-4434-8a08-a92e780c8eb6', 'Reemplazar análisis por discursos de optimismo.', false, 'Incorrecto. El optimismo sin evidencia puede ocultar riesgos.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('ad6f3459-a82a-4ff5-85b7-2a9f300fb3e7', '257ab555-97b1-4434-8a08-a92e780c8eb6', 'Identificar amenazas, incumplimientos o estigmatización y corregir antes del daño.', true, 'Correcto. Leer señales tempranas sostiene la transición y protege comunidades.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('a0be1697-0eed-4188-974e-02f0ae36cdde', '4ce5e6db-f926-4428-87a6-26027d0d5953', 'Impedir todo diálogo social.', false, 'Incorrecto. La memoria puede facilitar diálogo si se trabaja con respeto y pluralidad.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('32e35b39-bc0d-49c8-b34d-5102b41ffa41', '4ce5e6db-f926-4428-87a6-26027d0d5953', 'Convertir el daño en aprendizaje público y reconocimiento de lo que no debe repetirse.', true, 'Correcto. Ayuda a dignificar víctimas y orientar garantías de no repetición.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('25beed2a-acca-42be-95f3-56b28592a8c7', '4ce5e6db-f926-4428-87a6-26027d0d5953', 'Sustituir la reparación material.', false, 'Incorrecto. No reemplaza reparación material, psicosocial o territorial.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('5b8af4e8-9f60-4d6c-9776-8b488d9c51ef', '4ce5e6db-f926-4428-87a6-26027d0d5953', 'Eliminar la necesidad de seguridad humana.', false, 'Incorrecto. La seguridad humana sigue siendo indispensable para participar sin miedo.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('8e4a1bda-cb39-4099-a59a-c66e8fa9f3c1', '5cc7e607-b278-45ce-a2a1-036259b839b7', 'Articular investigación penal y medidas colectivas.', false, 'Incorrecto. La investigación y la protección colectiva fortalecen prevención.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('446c4586-7665-45a2-b185-403cb40ab781', '5cc7e607-b278-45ce-a2a1-036259b839b7', 'Reconocer riesgos territoriales específicos.', false, 'Incorrecto. El análisis territorial mejora pertinencia.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('1791fdde-7c63-415c-9d80-097ba6f3ad88', '5cc7e607-b278-45ce-a2a1-036259b839b7', 'Reducirse a esquemas individuales sin abordar causas comunitarias del riesgo.', true, 'Correcto. Los riesgos suelen ser colectivos y requieren acción integral.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('fa3a5dbf-c710-4e79-a526-b507646e9b6e', '5cc7e607-b278-45ce-a2a1-036259b839b7', 'Incluir participación local y rutas de denuncia seguras.', false, 'Incorrecto. La participación local ayuda a diseñar medidas confiables.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('bb5cafe9-1fef-4822-9cb2-f3003c9e431d', '1cbfd327-f943-4ed5-a801-a7255f30fa35', 'Sostener derechos, confianza, participación y capacidades institucionales en el tiempo.', true, 'Correcto. La paz sostenible requiere continuidad, coordinación y legitimidad.', 0, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('e407a23b-4e47-4ca7-a7c1-03c9f9708f6c', '1cbfd327-f943-4ed5-a801-a7255f30fa35', 'Confiar en que la paz se mantiene sola después del acuerdo.', false, 'Incorrecto. El postconflicto necesita implementación, seguimiento y prevención.', 1, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('caaa2e81-0d68-4d36-9403-0cd6cb9d7aee', '1cbfd327-f943-4ed5-a801-a7255f30fa35', 'Separar justicia restaurativa de políticas públicas territoriales.', false, 'Incorrecto. La justicia restaurativa requiere entorno institucional y social.', 2, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
INSERT INTO public.opciones_respuesta (id, pregunta_id, texto, es_correcta, retroalimentacion, orden, created_at, updated_at) VALUES ('04488992-d98e-4532-a8be-f1226d6ba57f', '1cbfd327-f943-4ed5-a801-a7255f30fa35', 'Priorizar informes formales sobre experiencias comunitarias.', false, 'Incorrecto. Los informes deben dialogar con lo que viven víctimas y comunidades.', 3, '2026-07-30 16:45:23.162917+00', '2026-07-30 16:45:23.162917+00');
